window.HHC_YI_COMPLETE_READINGS={"3":[{"position":1,"title":"Nền chưa vững","text":"Hình ảnh quanh quẩn lúc khởi đầu gợi việc ổn định chỗ đứng và tìm người cùng xây nền.","tip":"Chốt việc nhỏ có thể làm đều trước khi mở rộng kế hoạch."},{"position":2,"title":"Chưa vội nhận lời","text":"Ngựa xoay vòng và chuyện hôn phối trì hoãn gợi sự thận trọng khi chưa rõ ý định của nhau.","tip":"Làm rõ đề nghị; cho mình thời gian trước một cam kết dài hạn."},{"position":3,"title":"Đừng vào rừng thiếu người dẫn","text":"Đuổi hươu mà không có người chỉ đường gợi một mục tiêu hấp dẫn nhưng thiếu hiểu biết cần thiết.","tip":"Tìm hướng dẫn hoặc dừng sớm khi chưa đủ thông tin."},{"position":4,"title":"Chủ động tìm sự hợp tác","text":"Đoàn ngựa còn do dự nhưng có ý tìm kết nối gợi một trở ngại có thể tháo bằng lời đề nghị rõ ràng.","tip":"Nói điều mình cần và hỏi đối phương có sẵn lòng cùng làm."},{"position":5,"title":"Chia nguồn lực từng bước","text":"Phần nuôi dưỡng khó lưu chuyển gợi điều kiện chưa đủ cho một việc lớn, dù việc nhỏ vẫn có thể tiến.","tip":"Thu hẹp phạm vi và kiểm nguồn lực trước khi cam kết thêm."},{"position":6,"title":"Thoát khỏi vòng bế tắc","text":"Ngựa quanh quẩn và nước mắt gợi sự kiệt sức khi cứ lặp lại một cách đi không có lối ra.","tip":"Dừng nhịp cũ, tìm trợ giúp và chọn một bước khác khả thi."}],"4":[{"position":1,"title":"Học bằng khuôn phép vừa đủ","text":"Mở sự mông muội đi cùng tháo gông gợi việc dùng kỷ luật để giúp hiểu biết, không kéo dài sự cưỡng ép.","tip":"Thống nhất nguyên tắc học rồi để người học tự thực hành."},{"position":2,"title":"Dung chứa điều chưa biết","text":"Bao dung người còn non và khả năng gánh việc nhà gợi một môi trường học có nâng đỡ lẫn trách nhiệm.","tip":"Chia việc vừa sức, hướng dẫn và cho cơ hội sửa sai."},{"position":3,"title":"Giữ quyền tự chủ","text":"Hình ảnh bị hấp dẫn bởi người có của gợi nguy cơ đánh mất chính mình khi chọn một mối gắn bó.","tip":"Kiểm động cơ và ranh giới của mình trước lời hứa hấp dẫn."},{"position":4,"title":"Mở lối cho hiểu biết","text":"Mắc kẹt trong sự mông muội gợi tình trạng thiếu người trao đổi hoặc không chịu tiếp nhận điều mới.","tip":"Nêu một câu hỏi cụ thể và tìm người có năng lực giải thích."},{"position":5,"title":"Giữ tâm thế người học","text":"Hình ảnh trẻ thơ học hỏi gợi sự cởi mở và khả năng tiến bộ khi chưa tự cho mình biết hết.","tip":"Thử lại từ căn bản; hỏi ngay điều chưa hiểu."},{"position":6,"title":"Chấn chỉnh để bảo vệ","text":"Đánh thức sự mê mờ cần nhằm ngăn điều sai, không biến việc dạy thành công kích hay áp đặt.","tip":"Sửa hành vi cụ thể và giải thích lý do, tránh làm người khác nhục."}],"5":[{"position":1,"title":"Chờ ở khoảng an toàn","text":"Chờ ngoài đồng gợi một khoảng cách còn đủ rộng để giữ bình tĩnh và bền nhịp chuẩn bị.","tip":"Tiếp tục việc nền tảng trong khi chờ dữ kiện mới."},{"position":2,"title":"Đừng mắc vào lời qua tiếng lại","text":"Chờ trên cát, có ít lời bàn gợi việc tiến gần điều khó nhưng chưa cần phản ứng với mọi ý kiến.","tip":"Kiểm thông tin chính và hạn chế tranh luận không giúp công việc tiến lên."},{"position":3,"title":"Rút khỏi chỗ lún","text":"Chờ trong bùn gợi một vị trí dễ vướng và khiến rắc rối tìm đến vì đã tiến quá sâu.","tip":"Giảm mức tiếp xúc với việc đang kéo mình vào thế bị động."},{"position":4,"title":"Tìm đường ra khỏi áp lực","text":"Chờ giữa thương tổn rồi ra khỏi hố gợi nhu cầu thoát một thế bị bao vây trước khi tính chuyện khác.","tip":"Ưu tiên một lối rút an toàn và nhờ người hỗ trợ."},{"position":5,"title":"Dưỡng sức trong lúc chờ","text":"Chờ bên thức ăn thức uống gợi thời gian có thể chăm nguồn lực và giữ nếp sống ổn định.","tip":"Ăn nghỉ điều độ, chuẩn bị kỹ thay vì sốt ruột thúc việc."},{"position":6,"title":"Đón điều bất ngờ có chừng mực","text":"Khách không hẹn tới lúc ở trong hố gợi cơ hội nhận trợ giúp từ tình huống ngoài dự kiến.","tip":"Lắng nghe lịch sự rồi kiểm mức phù hợp trước khi nhận lời."}],"6":[{"position":1,"title":"Khép tranh chấp từ sớm","text":"Không kéo dài việc kiện tụng gợi khả năng tránh hao tổn dù vẫn có vài lời không thuận tai.","tip":"Giải quyết một điểm bất đồng cụ thể và chốt cách kết thúc."},{"position":2,"title":"Lùi để giữ người liên quan","text":"Không thắng cuộc tranh rồi trở về gợi việc dừng hơn thua để bảo toàn phần việc và cộng đồng quanh mình.","tip":"Cân nhắc chi phí lan sang người khác trước khi tiếp tục đối đầu."},{"position":3,"title":"Tựa vào điều đã xây","text":"Sống bằng đức cũ và góp việc mà không giành công gợi cách giữ nền tảng trong hoàn cảnh dễ va chạm.","tip":"Làm đúng trách nhiệm và giữ bằng chứng rõ ràng về thỏa thuận."},{"position":4,"title":"Đổi cách hành xử","text":"Không tiếp tục tranh, trở lại điều đã định và thay đổi thái độ gợi lối ra bằng tự điều chỉnh.","tip":"Sửa một đòi hỏi thiếu thực tế và tìm phương án hai bên chấp nhận."},{"position":5,"title":"Tìm sự phân xử công bằng","text":"Hào ở trung tâm việc phân xử gợi giá trị của một cách giải quyết rõ ràng, đúng thẩm quyền.","tip":"Đưa sự việc về quy trình và người có trách nhiệm xử lý."},{"position":6,"title":"Đừng coi phần thưởng là nền vững","text":"Dải đai được ban rồi bị tước nhiều lần gợi sự bấp bênh của lợi ích đạt bằng tranh hơn thua.","tip":"Đánh giá độ bền của thỏa thuận thay vì chỉ nhìn thắng lợi trước mắt."}],"7":[{"position":1,"title":"Thống nhất kỷ luật khi bắt đầu","text":"Đoàn quân xuất phát cần phép tắc gợi một nhóm hành động sẽ dễ rối nếu chưa thống nhất cách phối hợp.","tip":"Nêu rõ mục tiêu, vai trò và nguyên tắc trước khi cùng làm."},{"position":2,"title":"Lãnh đạo từ trong tập thể","text":"Người đứng giữa đội ngũ và được giao trách nhiệm gợi vai trò điều phối có mặt tại nơi công việc diễn ra.","tip":"Theo sát tình hình và hỗ trợ người thực hiện, thay vì chỉ ra lệnh."},{"position":3,"title":"Nhìn lại tổn thất của cách dẫn dắt","text":"Hình ảnh xe chở người chết gợi hậu quả nặng của việc phối hợp sai hoặc giao quyền thiếu phù hợp.","tip":"Dừng cách tổ chức đang gây hao tổn và rà lại trách nhiệm chỉ huy."},{"position":4,"title":"Lùi có tổ chức","text":"Đội quân tạm rút về một phía gợi một bước lui chiến thuật có thể giúp giữ lực lượng.","tip":"Giữ liên lạc, nguồn lực và tiêu chí rõ ràng cho lúc trở lại."},{"position":5,"title":"Giao quyền đúng người","text":"Việc ra tay cần lý do rõ và người có kinh nghiệm dẫn dắt; nhiều đầu mối thiếu năng lực dễ gây tổn thất.","tip":"Chọn một người chịu trách nhiệm chính và xác định phạm vi hành động."},{"position":6,"title":"Đặt nền sau khi hoàn thành","text":"Sau chiến dịch là lúc giao việc và dựng trật tự; lời cảnh giác nhắc không trao quyền chỉ vì công trạng nhất thời.","tip":"Chọn người bằng năng lực lẫn cách hành xử khi phân trách nhiệm lâu dài."}],"8":[{"position":1,"title":"Kết nối bằng lòng thành","text":"Chiếc vò đầy lòng tin gợi sự gắn bó bắt đầu từ điều giản dị nhưng chân thực.","tip":"Giữ một lời hứa nhỏ và làm rõ điều hai bên mong đợi."},{"position":2,"title":"Gắn bó từ sự đồng lòng","text":"Kết nối từ bên trong gợi sự hợp tác phù hợp giá trị, thay vì chỉ chạy theo lời mời bên ngoài.","tip":"Xác định điều mình cùng tin trước khi tham gia một nhóm."},{"position":3,"title":"Xem lại người đang đồng hành","text":"Gắn với người không phù hợp gợi rủi ro của việc đặt niềm tin sai chỗ.","tip":"Quan sát cách họ thực hiện cam kết trước khi giao thêm trách nhiệm."},{"position":4,"title":"Mở kết nối ra ngoài","text":"Tìm sự gắn bó ngoài phạm vi quen thuộc gợi cơ hội hợp tác khi vẫn giữ nguyên tắc.","tip":"Chủ động gặp người mới nhưng nói rõ giới hạn và mục tiêu của mình."},{"position":5,"title":"Để sự tham gia có tự nguyện","text":"Cuộc săn để lối thoát gợi cách thu hút công khai mà không ép mọi người theo mình.","tip":"Mời gọi minh bạch và tôn trọng lựa chọn không tham gia."},{"position":6,"title":"Tìm một điểm tựa chung","text":"Sự gắn bó không có đầu mối gợi một tập hợp thiếu định hướng hoặc nền tảng tin cậy.","tip":"Làm rõ ai chịu trách nhiệm và điều gì nối mọi người lại."}],"9":[{"position":1,"title":"Trở về cách làm đúng","text":"Quay về con đường của mình gợi việc sửa hướng trước khi đi quá xa.","tip":"Khôi phục một nếp làm đã chứng minh có ích."},{"position":2,"title":"Cùng kéo nhau trở lại","text":"Sự trở về nhờ liên kết gợi vai trò của người đồng hành khi cần điều chỉnh.","tip":"Nhờ một người nhắc nhở và cùng theo dõi việc đang sửa."},{"position":3,"title":"Sửa chỗ liên kết lỏng","text":"Xe tuột bộ phận và người thân phản mục gợi cách phối hợp đã mất ăn khớp.","tip":"Sửa quy trình và trao đổi kỳ vọng trước khi thúc công việc tiếp."},{"position":4,"title":"Lòng tin làm dịu căng thẳng","text":"Sự thành thực đi cùng nỗi lo được tháo gợi lối xử lý dựa vào tin cậy thay vì phòng thủ mãi.","tip":"Nói rõ một điều đang lo và đề nghị cách kiểm chứng cùng nhau."},{"position":5,"title":"Chia sẻ nguồn lực quanh mình","text":"Niềm tin nối kết và sự đủ đầy cùng hàng xóm gợi sức mạnh của mạng lưới tương trợ.","tip":"Chia sẻ điều có thể giúp nhóm, đồng thời thỏa thuận phần đóng góp."},{"position":6,"title":"Biết đủ khi điều kiện đã tới","text":"Mưa đã xuống, trăng gần tròn gợi một chặng tích lũy có thể dừng để ổn định, tránh tiếp tục ép tiến.","tip":"Giữ kết quả và giảm một mục tiêu đang vượt nhu cầu."}],"10":[{"position":1,"title":"Đi bằng sự giản dị","text":"Bước chân mộc mạc gợi cách tiến không cần phô bày vị thế hay trang bị quá mức.","tip":"Làm điều căn bản cho chắc trước khi đầu tư vào hình thức."},{"position":2,"title":"Giữ đường đi bằng phẳng","text":"Con đường rộng yên và người sống kín gợi nhịp tiến ổn định khi ít bị cuốn vào cạnh tranh.","tip":"Chọn cách làm rõ ràng, vừa sức và ít phụ thuộc việc gây chú ý."},{"position":3,"title":"Đừng vượt năng lực thực","text":"Mắt yếu chân yếu mà cứ giẫm đuôi hổ gợi sự liều lĩnh khi tự đánh giá quá cao khả năng.","tip":"Kiểm kỹ năng và mức rủi ro trước khi nhận việc nguy hiểm hoặc quá sức."},{"position":4,"title":"Thận trọng ở gần điều nhạy cảm","text":"Giẫm đuôi hổ với sự dè chừng gợi khả năng đi qua một tình thế căng khi hiểu giới hạn.","tip":"Chuẩn bị bước đi và tôn trọng quy tắc của hoàn cảnh."},{"position":5,"title":"Quyết đoán vẫn cần tự xét","text":"Bước đi cương quyết gợi sức hành động nhưng đồng thời nhắc nguy cơ cứng nhắc.","tip":"Xin phản biện cho một quyết định mình đang quá chắc chắn."},{"position":6,"title":"Nhìn lại cả hành trình","text":"Xem dấu chân và khảo xét tường tận gợi việc đánh giá kết quả bằng những gì đã làm.","tip":"Rà lại quá trình, rút một bài học trước khi mở chặng mới."}],"11":[{"position":1,"title":"Đổi mới cùng mạng lưới","text":"Nhổ cỏ kéo cả rễ gợi sự liên hệ giữa một hành động với những người, việc cùng nhóm.","tip":"Trao đổi với người bị ảnh hưởng trước khi thay đổi một mắt xích."},{"position":2,"title":"Bao dung mà không bỏ điều xa","text":"Dung chứa nơi hoang sơ, dám qua sông và không quên chỗ xa gợi phối hợp lòng rộng với sự công bằng.","tip":"Kiểm xem kế hoạch có bỏ sót nhóm ít được chú ý hay không."},{"position":3,"title":"Chuẩn bị cho lúc đổi chiều","text":"Không có bằng phẳng mãi, đi rồi sẽ trở lại gợi chu kỳ biến đổi ngay trong thời thuận.","tip":"Củng cố phương án dự phòng trong lúc nguồn lực còn đủ."},{"position":4,"title":"Tin nhau vượt tính toán giàu nghèo","text":"Sự gần gũi giữa hàng xóm không dựa vào của cải gợi liên kết bằng thành ý.","tip":"Góp một phần công sức thiết thực thay vì chỉ đo giá trị bằng tiền."},{"position":5,"title":"Kết nối bằng sự nhún nhường","text":"Hình tượng một cuộc hôn phối vương thất gợi hòa hợp nhờ hạ mình và chấp nhận liên kết.","tip":"Chọn cách trao đổi tôn trọng vị thế của cả hai bên."},{"position":6,"title":"Đừng dùng sức giữ thời đã đổi","text":"Tường thành đổ về hào gợi nền bảo vệ cũ đã yếu; huy động thêm đối đầu có thể làm hao tổn.","tip":"Thu về phạm vi kiểm soát được và sửa nền trước."}],"12":[{"position":1,"title":"Giữ nguyên tắc cùng người liên quan","text":"Rễ cỏ nối nhau trong lúc bế tắc gợi tác động lan truyền của cách mình giữ chỗ đứng.","tip":"Cùng nhóm thống nhất điều nên giữ và việc nên tạm dừng."},{"position":2,"title":"Phân biệt hòa thuận với chiều ý","text":"Sự dung nạp theo người khác gợi một cách sống còn có ích ngắn hạn nhưng dễ lệch giá trị.","tip":"Đặt giới hạn rõ với một thỏa hiệp đang làm mình khó xử."},{"position":3,"title":"Nhìn thẳng điều đáng ngại","text":"Ôm giữ sự hổ thẹn gợi những thiếu sót bị che lại thay vì xử lý.","tip":"Thừa nhận một sai lệch và sửa bằng hành động cụ thể."},{"position":4,"title":"Hành động khi có trách nhiệm rõ","text":"Nhận mệnh và cùng người đồng chí hưởng điều lành gợi lúc có thể tiến nhờ sự giao phó chính đáng.","tip":"Xác nhận quyền hạn, trách nhiệm và người phối hợp trước khi thực hiện."},{"position":5,"title":"Giữ chắc sau khi tháo bế tắc","text":"Buộc vào gốc dâu vững gợi việc vừa có lối mở đã cần nghĩ đến chỗ dễ mất.","tip":"Củng cố một điều kiện then chốt thay vì chủ quan vì tiến triển mới."},{"position":6,"title":"Mở một chu kỳ khỏi trì trệ","text":"Bế tắc bị lật chuyển, trước khó sau vui gợi khả năng khép một nhịp lâu ngày không thông.","tip":"Tận dụng lối mở để thay quy trình cũ, không chỉ đổi người làm."}],"13":[{"position":1,"title":"Bắt đầu kết nối ở cửa","text":"Gặp nhau tại cửa gợi sự hợp tác công khai, dễ tiếp cận ngay từ bước đầu.","tip":"Nói rõ mục tiêu và mời người liên quan cùng tham gia."},{"position":2,"title":"Tránh thu hẹp thành phe nhóm","text":"Chỉ cùng người trong họ gợi sự gắn kết quá hẹp, dễ bỏ qua người bên ngoài.","tip":"Mở thêm một tiếng nói khác với nhóm quen thuộc."},{"position":3,"title":"Gỡ nghi kỵ trước khi tiến","text":"Giấu quân trong bụi và nhìn từ gò cao gợi sự phòng bị kéo dài vì thiếu tin cậy.","tip":"Trao đổi dữ kiện có thể kiểm và giảm hành động thăm dò đối đầu."},{"position":4,"title":"Chọn dừng công kích","text":"Đã lên tường mà không tấn công gợi khả năng nhận ra giới hạn và đổi cách giải quyết.","tip":"Tìm một điểm có thể thỏa thuận thay vì tiếp tục dồn ép."},{"position":5,"title":"Đi qua trở ngại để gặp nhau","text":"Khóc rồi cười gợi kết nối phải vượt một ngăn cách thực sự, không chỉ nhờ thiện chí.","tip":"Xác định rào cản chung và phân việc tháo gỡ cho hai bên."},{"position":6,"title":"Đồng hành ở khoảng cách vừa đủ","text":"Gặp nhau ngoài đồng gợi quan hệ rộng nhưng chưa cần nhập thành một nhóm khăng khít.","tip":"Giữ thiện chí và một mức hợp tác phù hợp điều kiện hiện tại."}],"14":[{"position":1,"title":"Giữ mình khỏi sự tổn hại","text":"Chưa giao vào điều gây hại và biết khó gợi lợi ích của sự tỉnh táo khi nguồn lực đang có.","tip":"Rà một chỗ có thể làm hao hụt thành quả trước khi mở rộng."},{"position":2,"title":"Chở được nhờ sức chứa vững","text":"Cỗ xe lớn gợi khả năng mang trách nhiệm khi phương tiện và nền tảng tương xứng.","tip":"Kiểm đội ngũ và công cụ có chịu được quy mô mới hay không."},{"position":3,"title":"Chia thành quả đúng tư cách","text":"Dâng lễ lên người đứng đầu gợi dùng điều đang có vào việc chung với sự ngay thẳng.","tip":"Minh bạch đóng góp và tránh dùng quà tặng để đổi ưu ái."},{"position":4,"title":"Đừng đua theo sự phô trương","text":"Hào nhắc tránh điều quá mức trong sự đủ đầy; không cần hơn người bằng cách trưng bày.","tip":"Giảm một khoản phục vụ hình ảnh nhiều hơn nhu cầu thật."},{"position":5,"title":"Tin cậy đi cùng uy tín","text":"Thành tín nối nhau và vẻ nghiêm trang gợi ảnh hưởng được xây bằng cách hành xử nhất quán.","tip":"Giữ lời hứa và đặt giới hạn rõ khi điều phối người khác."},{"position":6,"title":"Đón thuận lợi bằng trách nhiệm","text":"Hình ảnh được nâng đỡ gợi một lúc có điều kiện thuận và sự hỗ trợ vượt phần nỗ lực riêng.","tip":"Ghi nhận người giúp và dùng thuận lợi để làm việc có ích."}],"15":[{"position":1,"title":"Khiêm nhường khi nhận việc khó","text":"Người khiêm lại càng khiêm mà qua sông lớn gợi sự chuẩn bị và không tự mãn trước thử thách.","tip":"Xin hỗ trợ chuyên môn cho phần mình còn thiếu trước khi bắt tay."},{"position":2,"title":"Để thái độ khiêm nhường được nhận ra","text":"Sự khiêm nhường có tiếng vang gợi một cách ứng xử nhất quán tự tạo niềm tin.","tip":"Lắng nghe phản hồi và thừa nhận đóng góp của người khác."},{"position":3,"title":"Có công vẫn giữ chừng mực","text":"Người làm việc vất vả mà khiêm gợi khả năng bền đến cuối nhờ không quá đặt nặng công danh.","tip":"Hoàn tất phần việc rồi chia sẻ công lao rõ ràng."},{"position":4,"title":"Thể hiện sự nhún nhường bằng hành động","text":"Khiêm nhường được đưa vào cách làm gợi việc điều chỉnh quan hệ thay vì chỉ nói lời mềm.","tip":"Nhường một không gian quyết định cho người có chuyên môn phù hợp."},{"position":5,"title":"Mềm mỏng nhưng có giới hạn","text":"Không dựa giàu có để nối hàng xóm và vẫn có việc phải chấn chỉnh gợi khiêm nhường không đồng nghĩa buông nguyên tắc.","tip":"Nêu một ranh giới cần giữ bằng lời rõ ràng, không đe dọa."},{"position":6,"title":"Sửa phần mình có trách nhiệm","text":"Sự khiêm nhường được nhắc cùng việc chỉnh đốn trong phạm vi mình gợi hành động bắt đầu từ nội bộ.","tip":"Rà việc của nhóm mình trước khi quy lỗi cho bên ngoài."}],"16":[{"position":1,"title":"Đừng khoe vui quá sớm","text":"Niềm vui cất tiếng phô bày gợi nguy cơ say với thuận lợi khi nền tảng còn chưa chắc.","tip":"Chờ kết quả thực và tránh hứa quá mức trong lúc hứng khởi."},{"position":2,"title":"Nhận ra điểm phải dừng","text":"Vững như đá và không chờ hết ngày gợi sự tỉnh táo nhận dấu hiệu để hành động kịp.","tip":"Chốt một tiêu chí dừng và xử lý ngay khi nó xuất hiện."},{"position":3,"title":"Đừng chờ người khác định nhịp mãi","text":"Ngẩng nhìn để tìm vui rồi chậm trễ gợi sự lệ thuộc vào phản ứng bên ngoài.","tip":"Tự xác định việc cần làm và một thời hạn thực tế."},{"position":4,"title":"Tạo khí thế để mọi người cùng góp","text":"Nguồn vui hút bạn bè tụ lại gợi một người hoặc mục tiêu có sức kết nối tập thể.","tip":"Đổi cảm hứng chung thành việc cụ thể và cách phối hợp rõ."},{"position":5,"title":"Giữ nhịp trong điều khó kéo dài","text":"Tình trạng khó chịu dai dẳng nhưng chưa kết thúc gợi nhu cầu điều tiết thay vì cố làm như không có trở ngại.","tip":"Giảm tải và giải quyết phần nằm trong khả năng kiểm soát."},{"position":6,"title":"Tỉnh ra khỏi sự mê vui","text":"Chìm trong hưởng thụ nhưng còn thay đổi được gợi cơ hội tự sửa trước khi một nếp xấu thành cố định.","tip":"Dừng một thói quen đang làm mình bỏ quên trách nhiệm."}],"17":[{"position":1,"title":"Đổi vai trò, mở quan hệ","text":"Chức trách thay đổi và bước ra cửa gợi sự thích nghi với cách kết nối mới.","tip":"Làm rõ vai trò hiện tại và tìm người phù hợp để phối hợp."},{"position":2,"title":"Chọn điều gắn bó có cân nhắc","text":"Giữ người non mà mất người trưởng thành gợi một lựa chọn có chi phí cơ hội.","tip":"Xem quan hệ hoặc việc nào giúp mình phát triển lâu dài."},{"position":3,"title":"Chấp nhận điều phải buông khi chọn","text":"Gắn với người trưởng thành mà mất điều nhỏ gợi không thể giữ mọi hướng cùng lúc.","tip":"Chốt ưu tiên và nói rõ phần mình không thể tiếp tục."},{"position":4,"title":"Đừng để lợi trước mắt dẫn đường","text":"Theo mà có thu hoạch nhưng vẫn nguy gợi sự hấp dẫn của kết quả dễ làm lệch nguyên tắc.","tip":"Kiểm cách đạt lợi ích có phù hợp điều mình coi trọng hay không."},{"position":5,"title":"Theo điều tốt bằng lòng tin","text":"Thành thực hướng tới điều đáng quý gợi sự chọn lựa dựa phẩm chất, không chỉ quyền thế.","tip":"Tìm một chuẩn mực đáng tin và thực hiện nhất quán."},{"position":6,"title":"Xem lại sự gắn kết sâu","text":"Bị buộc chặt rồi gắn với việc cúng tế gợi một liên kết có sức ràng buộc và ý nghĩa lâu dài.","tip":"Xác nhận cam kết là tự nguyện và còn phù hợp giá trị của mình."}],"18":[{"position":1,"title":"Sửa việc cũ để người sau nối tiếp","text":"Sửa điều hỏng từ thế hệ trước gợi trách nhiệm kế thừa đi cùng khó khăn có thể vượt.","tip":"Tách lỗi của hệ thống khỏi việc trách cá nhân rồi bắt đầu sửa."},{"position":2,"title":"Sửa bằng sự mềm dẻo","text":"Chỉnh việc cũ gắn với hình tượng người mẹ gợi cách thay đổi cần thấu hiểu quan hệ và hoàn cảnh.","tip":"Chọn cách góp ý giữ được đối thoại thay vì ép một khuôn cứng."},{"position":3,"title":"Chấp nhận phần khó của sửa sai","text":"Chỉnh việc cha để lại có ít hối tiếc gợi thay đổi đúng việc vẫn có thể gây va chạm.","tip":"Giải thích mục đích và điều chỉnh cách làm khi có phản hồi."},{"position":4,"title":"Đừng dung dưỡng chỗ đã hỏng","text":"Nới cho lỗi cũ tiếp tục gợi nguy cơ để sự xuống cấp đi xa hơn.","tip":"Đặt thời hạn sửa một việc mà nhóm đã trì hoãn nhiều lần."},{"position":5,"title":"Sửa tận gốc để lấy lại tin cậy","text":"Chấn chỉnh được việc cũ và có tiếng tốt gợi uy tín đến từ kết quả sửa chữa thực chất.","tip":"Công khai bước cải thiện có thể đo và người chịu trách nhiệm."},{"position":6,"title":"Giữ một việc có ý nghĩa riêng","text":"Không phụng sự vương hầu gợi lựa chọn giữ phẩm giá và mục đích thay vì chạy theo địa vị.","tip":"Dành sức cho điều có ích và phù hợp lương tâm của mình."}],"19":[{"position":1,"title":"Đến gần bằng sự đồng cảm","text":"Sự tiếp cận có cảm ứng gợi bắt đầu quan hệ bằng việc hiểu nhu cầu của nhau.","tip":"Hỏi và lắng nghe trước khi đưa ra hướng giải quyết."},{"position":2,"title":"Cùng hưởng ứng một việc có ích","text":"Tiếp cận bằng sự đồng lòng gợi thuận lợi khi người tham gia cùng hiểu mục tiêu.","tip":"Xác nhận điểm chung rồi phân chia phần việc rõ ràng."},{"position":3,"title":"Đừng chỉ dùng lời ngọt","text":"Sự tiếp cận ngọt ngào mà ít ích gợi lời hứa dễ chịu chưa thay được hành động.","tip":"Nhận ra chỗ thiếu thực chất và sửa bằng một cam kết kiểm được."},{"position":4,"title":"Có mặt đúng nơi cần mình","text":"Đến gần một cách trọn vẹn gợi sự hiện diện chân thành thay vì quan tâm từ xa.","tip":"Dành thời gian trực tiếp xử lý điều người liên quan đang cần."},{"position":5,"title":"Dẫn dắt bằng sự hiểu biết","text":"Tiếp cận với trí sáng gợi người điều phối hiểu việc và biết dùng năng lực của người khác.","tip":"Hỏi đúng chuyên môn, giao quyền phù hợp và theo dõi kết quả."},{"position":6,"title":"Giữ sự quan tâm bền hậu","text":"Cách đến gần đôn hậu gợi ảnh hưởng được nuôi bằng lòng rộng và sự bền lòng.","tip":"Hỗ trợ đều đặn mà không tạo sự lệ thuộc hay áp đặt."}],"20":[{"position":1,"title":"Mở rộng cái nhìn non trẻ","text":"Cái nhìn như trẻ nhỏ gợi giới hạn quan sát khi mới tiếp xúc; người có trách nhiệm cần hiểu sâu hơn.","tip":"Tìm thêm góc nhìn trước khi đưa ra nhận định ảnh hưởng người khác."},{"position":2,"title":"Nhận ra khung nhìn bị hẹp","text":"Nhìn qua khe cửa gợi chỉ thấy một phần sự việc. Hình tượng vai giới trong cổ văn không quyết định khả năng người dùng.","tip":"Kiểm điều đang khuất khỏi tầm nhìn rồi mới kết luận."},{"position":3,"title":"Dùng trải nghiệm để chọn tiến lui","text":"Quan sát đời mình gợi xem cách đã sống và kết quả thực để điều chỉnh đường đi.","tip":"So một quyết định cũ với kết quả, rồi chọn điều cần sửa."},{"position":4,"title":"Học từ điều tốt của cộng đồng","text":"Nhìn ánh sáng của đất nước và làm khách gợi cơ hội học cách tổ chức có giá trị.","tip":"Quan sát một môi trường tốt và chọn điểm có thể áp dụng vừa sức."},{"position":5,"title":"Tự xét ở vị trí có ảnh hưởng","text":"Quan sát đời mình gợi trách nhiệm nhìn lại tác động của cách mình hành xử.","tip":"Xin phản hồi từ người chịu ảnh hưởng bởi quyết định của mình."},{"position":6,"title":"Nhìn xa hơn lợi ích riêng","text":"Quan sát đời sống của người khác gợi tầm nhìn rộng và khả năng tự điều chỉnh từ thực tế chung.","tip":"Đánh giá kế hoạch theo cả lợi ích của người liên quan."}],"21":[{"position":1,"title":"Chấn chỉnh từ sai lệch ban đầu","text":"Hình ảnh bị ngăn ở chân gợi một giới hạn sớm giúp dừng việc sai trước khi thành chuyện lớn.","tip":"Đặt nguyên tắc rõ và biện pháp sửa tương xứng, không dùng bạo lực."},{"position":2,"title":"Xử lý điều tưởng dễ vẫn cần chừng mực","text":"Cắn phần mềm đến khuất mũi gợi sự quá tay khi giải quyết một việc có vẻ đơn giản.","tip":"Kiểm mức can thiệp cần thiết, tránh dồn ép vượt mục đích ban đầu."},{"position":3,"title":"Gặp phản ứng khi chạm việc cũ","text":"Cắn thịt khô gặp chất độc gợi trở lực hoặc lời khó chịu khi xử lý vấn đề tồn lâu.","tip":"Tách dữ kiện khỏi phản ứng và nhờ đúng chuyên môn khi cần."},{"position":4,"title":"Bền lòng tháo nút cứng","text":"Cắn phần khó và tìm được mũi tên kim loại gợi việc cứng cần sự kiên trì cùng chứng cứ rõ.","tip":"Thu thập dữ kiện và xử lý từng bước theo quy trình phù hợp."},{"position":5,"title":"Công bằng khi có quyền xử lý","text":"Phần thịt khô cùng vàng gợi phẩm chất cân bằng và sự cảnh giác trong lúc phân xử.","tip":"Kiểm xung đột lợi ích trước một quyết định liên quan nhiều người."},{"position":6,"title":"Đừng để sai lệch tích tụ","text":"Gông che tai gợi tình trạng đến mức không còn nghe lời nhắc; đây là hình tượng cảnh tỉnh, không dự báo hình phạt.","tip":"Lắng nghe phản hồi khó nghe và sửa điều đã bị nhắc nhiều lần."}],"22":[{"position":1,"title":"Chọn bước chân giản dị","text":"Trang sức ở chân rồi bỏ xe đi bộ gợi coi trọng cách tự mình làm hơn phương tiện phô trương.","tip":"Chọn cách trình bày phù hợp năng lực và điều kiện thực tế."},{"position":2,"title":"Hình thức nên đi cùng nội dung","text":"Trang sức cho bộ râu gợi vẻ ngoài đi theo phần mà nó gắn vào, không tự tạo giá trị riêng.","tip":"Làm rõ nội dung trước khi chỉnh cách thể hiện."},{"position":3,"title":"Đẹp mà vẫn giữ nền","text":"Vẻ sáng nhuần gợi sức hấp dẫn đang có; điều cần giữ lâu dài là sự nhất quán bên trong.","tip":"Kiểm lời giới thiệu có khớp chất lượng thực hay không."},{"position":4,"title":"Nhận rõ ý tốt sau vẻ lạ","text":"Ngựa trắng và người đến cầu kết nối gợi sự giản dị hoặc khác lạ không nhất thiết là đe dọa.","tip":"Hỏi rõ ý định thay vì phán đoán chỉ từ hình thức."},{"position":5,"title":"Quà ít vẫn có thành ý","text":"Lụa mỏng nơi đồi vườn gợi hoàn cảnh giản dị nhưng chân thành có thể tạo kết nối tốt.","tip":"Chọn sự quan tâm thiết thực thay vì cố tặng vượt khả năng."},{"position":6,"title":"Trở về vẻ đẹp không cầu kỳ","text":"Màu trắng giản phác gợi gỡ bỏ phần trang sức dư để thấy chất lượng thật.","tip":"Bỏ một chi tiết rườm rà đang làm mờ điều quan trọng."}],"23":[{"position":1,"title":"Gia cố chân nền","text":"Giường bị bóc từ chân gợi suy yếu bắt đầu nơi nâng đỡ nhưng dễ bị bỏ qua.","tip":"Kiểm một điều kiện căn bản đang xuống cấp và sửa sớm."},{"position":2,"title":"Đừng bỏ qua hư hại đang lan","text":"Sự bóc mòn lên phần khung gợi một vấn đề nền tảng đã vượt dấu hiệu ban đầu.","tip":"Giảm tải và kiểm phần liên kết trước khi tiếp tục sử dụng."},{"position":3,"title":"Rời khỏi điều đang làm hỏng","text":"Tách ra giữa quá trình bóc mòn gợi khả năng tránh tiếp tay cho một nếp làm xấu.","tip":"Chọn dừng tham gia vào việc đi ngược nguyên tắc của mình."},{"position":4,"title":"Ưu tiên khi tổn hại đã sát mình","text":"Bóc giường đến da gợi tình thế cần bảo vệ điều thiết yếu trước khi tính chuyện cải thiện xa.","tip":"Dừng mức chịu đựng quá sức và tìm sự hỗ trợ phù hợp."},{"position":5,"title":"Sắp lại quan hệ theo trật tự","text":"Chuỗi cá và người trong cung gợi sự phối hợp có thứ tự; không lấy thứ bậc cổ làm khuôn cho giá trị con người.","tip":"Làm rõ vai trò để mọi người được tham gia và được tôn trọng."},{"position":6,"title":"Giữ hạt giống cho chặng sau","text":"Quả lớn còn lại và chiếc xe nâng đỡ gợi việc giữ nguồn lực cùng người đồng hành; tự phá mái che sẽ làm mất nơi nương.","tip":"Giữ một nguồn lực cốt lõi và tìm sự hỗ trợ trước khi dùng hết phần dự phòng."}],"24":[{"position":1,"title":"Sửa hướng khi chưa đi xa","text":"Trở về sớm gợi khả năng tự nhận sai mà chưa để hậu quả chồng chất.","tip":"Sửa ngay một bước lệch và không phí sức vào tự trách kéo dài."},{"position":2,"title":"Trở lại điều làm mình vững","text":"Sự trở về tốt đẹp gợi môi trường và người đồng hành giúp phục hồi nếp đúng.","tip":"Quay lại một thói quen có ích cùng người hỗ trợ mình."},{"position":3,"title":"Kiên trì qua những lần tái phạm","text":"Trở lại nhiều lần gợi việc sửa thói quen chưa ổn định; khó khăn không xóa giá trị của nỗ lực quay về.","tip":"Tìm nguyên nhân lặp lại và đặt một hàng rào hỗ trợ cụ thể."},{"position":4,"title":"Giữ hướng dù đi khác số đông","text":"Giữa đoàn người mà một mình quay lại gợi khả năng tự chọn khi đã nhận ra điều cần đổi.","tip":"Nói rõ lý do và thực hiện bước sửa nằm trong trách nhiệm mình."},{"position":5,"title":"Trở về bằng sự chân thành","text":"Sự trở về đôn hậu gợi thay đổi từ bên trong, không chỉ để tránh lời chê.","tip":"Chọn một nếp sống muốn giữ và thực hiện đều đặn."},{"position":6,"title":"Dừng khi đã mất phương hướng","text":"Lạc đường trở về cùng hình tượng chiến dịch thất bại gợi cái giá của cố tiến khi chưa tự xét.","tip":"Tạm dừng kế hoạch lớn, xác định lại mục tiêu và dữ kiện nền."}],"25":[{"position":1,"title":"Hành động không quanh co","text":"Sự không vọng tưởng gợi cách tiến ngay thẳng và ít tạo mưu tính vượt điều thực biết.","tip":"Nêu điều mình biết, điều chưa biết và làm đúng phần đã nhận."},{"position":2,"title":"Đừng chỉ chăm chăm vào phần thu","text":"Hình ảnh gieo cày và thu hoạch gợi làm việc theo điều cần làm, không bị lợi ích tưởng tượng kéo lệch.","tip":"Chăm chất lượng công việc và kiểm kỳ vọng về thành quả."},{"position":3,"title":"Phân biệt tai vạ với lỗi của mình","text":"Con bò bị người qua đường lấy khiến dân làng mang họa gợi hậu quả có thể đến từ việc ngoài ý mình.","tip":"Kiểm nguyên nhân và trách nhiệm thực tế trước khi tự nhận lỗi."},{"position":4,"title":"Giữ điều đúng khi chưa cần đổi","text":"Có thể giữ vững gợi sự ổn định của một cách làm còn phù hợp, không cần thay chỉ vì nóng ruột.","tip":"Kiểm bằng dữ kiện rồi duy trì điều đang có ích."},{"position":5,"title":"Không áp hình tượng bệnh vào điều trị","text":"Hào nói về một khó chịu không do vọng động, gợi đừng thêm can thiệp thiếu căn cứ. Lời cổ không phải chỉ dẫn dùng hay ngừng thuốc.","tip":"Với sức khỏe, quyết định theo đánh giá của nhân viên y tế."},{"position":6,"title":"Biết lúc ngay thẳng vẫn chưa nên tiến","text":"Không vọng mà đi vẫn gặp trở ngại gợi thiện ý không thay được điều kiện hành động.","tip":"Chờ thêm dữ kiện và tránh biến ý tốt thành sức ép."}],"26":[{"position":1,"title":"Nhận ra giới hạn để dừng","text":"Có nguy mà dừng được gợi sự tự chủ khi nguồn lực chưa đủ cho việc đang muốn.","tip":"Dừng một bước có rủi ro trước khi buộc phải trả giá."},{"position":2,"title":"Tháo động lực để giữ xe","text":"Xe tháo bộ phận vận hành gợi chủ động ngăn đà tiến trong lúc cần dưỡng sức hoặc kiểm tra.","tip":"Tạm khóa một cam kết mới để hoàn tất việc đang dang dở."},{"position":3,"title":"Luyện sẵn trước ngày tiến","text":"Ngựa tốt cùng việc luyện xe, phòng vệ gợi năng lực cần rèn tập; khi tiến vẫn phải bền chí và thận trọng.","tip":"Thử một tình huống khó, kiểm phương án dự phòng rồi mới tiến."},{"position":4,"title":"Ngăn từ lúc còn nhỏ","text":"Thanh ngăn sừng bò non gợi xử lý sớm trước khi một sức mạnh trở nên khó điều chỉnh.","tip":"Đặt nguyên tắc ngay khi bắt đầu thói quen hoặc dự án mới."},{"position":5,"title":"Giải quyết nguyên nhân thay vì đối đầu","text":"Hình tượng nanh lợn đã thuần bớt sức dữ gợi loại bỏ động lực gây hại từ gốc.","tip":"Tìm cơ chế đang nuôi vấn đề rồi chỉnh cơ chế đó."},{"position":6,"title":"Mở đường khi đã đủ nền","text":"Con đường rộng của trời gợi lúc sự tích lũy và tự chế có thể chuyển thành khả năng hành động.","tip":"Chọn mục tiêu rõ để dùng điều đã học vào việc hữu ích."}],"27":[{"position":1,"title":"Đừng bỏ năng lực tự nuôi mình","text":"Bỏ rùa thiêng nhìn hàm người khác gợi đánh mất nguồn lực riêng vì thèm điều bên ngoài.","tip":"Kiểm điều mình đã có và dùng nó trước khi so với người khác."},{"position":2,"title":"Xem nguồn hỗ trợ có đúng chỗ","text":"Tìm nuôi dưỡng trái nếp và hướng lên gò gợi sự lệ thuộc vào một nguồn không phù hợp.","tip":"Làm rõ ai có thể hỗ trợ và mức trách nhiệm thực sự của họ."},{"position":3,"title":"Đổi nếp nuôi dưỡng đang lệch","text":"Đi ngược cách nuôi dưỡng gợi một thói quen tiếp nhận hoặc trao đi đang làm cạn nguồn lực.","tip":"Dừng nguồn thông tin hay nghĩa vụ liên tục gây hao hụt vô ích."},{"position":4,"title":"Tập trung vào nguồn nuôi đúng","text":"Cái nhìn chăm chú như hổ gợi sự quan sát và mong cầu rõ ràng khi tìm điều cần cho đời sống.","tip":"Xác định nhu cầu thật và chọn nguồn đáp ứng có thể tin cậy."},{"position":5,"title":"Ở yên khi còn cần nương tựa","text":"Lời giữ chỗ và chưa qua sông lớn gợi điều kiện hỗ trợ chưa đủ cho một cuộc chuyển đổi lớn.","tip":"Củng cố sinh hoạt và nguồn lực trước khi thêm rủi ro."},{"position":6,"title":"Có trách nhiệm với việc nuôi người khác","text":"Làm nguồn nuôi dưỡng gợi ảnh hưởng lớn và yêu cầu cảnh giác trước khi nhận việc rộng hơn.","tip":"Đánh giá khả năng hỗ trợ bền lâu và phân chia gánh nặng."}],"28":[{"position":1,"title":"Lót kỹ trước khi đặt vật nặng","text":"Cỏ tranh trắng làm lớp đệm gợi sự cẩn trọng vượt mức thường khi việc mang tải lớn.","tip":"Thêm một bước bảo vệ nơi hậu quả sơ suất có thể đáng kể."},{"position":2,"title":"Giữ cơ hội hồi sinh thực chất","text":"Cây khô mọc chồi gợi một nền cũ vẫn có sức sống mới khi gặp điều kiện phù hợp.","tip":"Đầu tư vào dấu hiệu phát triển thật thay vì chỉ sửa hình ảnh."},{"position":3,"title":"Đừng để đòn gánh chịu quá tải","text":"Xà nhà cong gợi tải trọng đã vượt sức nâng đỡ của hệ thống.","tip":"Giảm việc, tăng hỗ trợ hoặc đổi cấu trúc trước khi tiếp tục."},{"position":4,"title":"Gia cố đúng điểm chịu lực","text":"Xà được nâng vững gợi giải pháp có thể phục hồi nền, nhưng ý định thêm việc dễ làm lệch.","tip":"Tập trung sửa điểm yếu chính và tránh kéo thêm mục tiêu phụ."},{"position":5,"title":"Phân biệt ra hoa với hồi phục","text":"Cây khô nở hoa gợi vẻ khởi sắc có thể đẹp mà không đủ sức duy trì lâu.","tip":"Kiểm nền nguồn lực trước khi gọi một dấu hiệu tốt là thay đổi bền."},{"position":6,"title":"Đừng tự nhận gánh vượt sức","text":"Lội sâu đến ngập đầu gợi hy sinh quá mức; thành ý không loại bỏ hậu quả của quá tải.","tip":"Giữ giới hạn và tìm người cùng gánh thay vì chịu một mình."}],"29":[{"position":1,"title":"Tìm chỗ đứng trước khi vùng vẫy","text":"Hết hố này đến hố khác gợi sự mắc kẹt lặp lại khi chưa tìm được điểm tựa.","tip":"Dừng lối thử bừa và nhờ hỗ trợ hiểu đúng tình thế."},{"position":2,"title":"Tìm kết quả nhỏ trong lúc khó","text":"Giữa hiểm mà cầu điều nhỏ gợi một mục tiêu vừa sức thay cho việc thoát hết ngay lập tức.","tip":"Chọn một bước giảm khó có thể hoàn thành hôm nay."},{"position":3,"title":"Không ép tiến khi đâu cũng vướng","text":"Đi hay đến đều gặp hố gợi điều kiện chưa thuận cho hành động theo nếp cũ.","tip":"Tạm dừng và tìm dữ kiện hoặc phương án khác trước khi tiến."},{"position":4,"title":"Chọn sự giản dị và đường đối thoại","text":"Rượu, đồ đựng mộc và cửa sổ gợi cách trao đổi thực chất giữa điều kiện chật hẹp.","tip":"Nói thẳng nhu cầu bằng lời giản dị và chọn kênh người kia tiếp nhận được."},{"position":5,"title":"Lấp vừa mức để vượt chỗ trũng","text":"Hố chưa đầy mà dần được san bằng gợi tiến bộ đến từ tích lũy đủ, không phải bước nhảy vội.","tip":"Sửa lần lượt các thiếu hụt cần thiết trước khi nhận việc mới."},{"position":6,"title":"Tháo điều đang trói mình","text":"Dây buộc và bụi gai gợi sự mất tự do kéo dài khi rắc rối không được giải quyết.","tip":"Xác định ràng buộc thật và tìm người có thẩm quyền hỗ trợ tháo gỡ."}],"30":[{"position":1,"title":"Giữ sự cẩn trọng giữa dấu chân rối","text":"Bước chân giao nhau gợi khởi đầu nhiều đầu mối cần thái độ chú tâm.","tip":"Làm rõ thứ tự việc và người chịu trách nhiệm để tránh nhầm lẫn."},{"position":2,"title":"Giữ độ sáng vừa phải","text":"Ánh vàng gợi sự sáng rõ có chừng mực, không chói gắt hoặc cực đoan.","tip":"Dùng thông tin đủ tin cậy và tránh đẩy quan điểm thành tuyệt đối."},{"position":3,"title":"Đón chặng chiều bằng sự thanh thản","text":"Mặt trời xế và tiếng hát hay than thở gợi cách mình ứng xử trước phần đời hay công việc đang đổi.","tip":"Khép một việc với sự trân trọng và chuẩn bị nhịp tiếp theo."},{"position":4,"title":"Giảm sức nóng của biến động đột ngột","text":"Lửa bùng lên rồi tàn gợi hành động dữ dội thiếu nền nâng đỡ, không phải lời dự báo cái chết.","tip":"Chậm lại trước phản ứng nóng và kiểm hậu quả của quyết định."},{"position":5,"title":"Thừa nhận nỗi buồn để tỉnh lại","text":"Nước mắt và tiếng than gợi sự nhận biết đau lòng có thể giúp con người thay đổi cách làm.","tip":"Nói điều đang khó với người tin cậy và chọn một bước chăm mình."},{"position":6,"title":"Xử lý đầu mối thay vì phạt cả nhóm","text":"Hình tượng chinh phạt nhấn vào thủ phạm gợi giải quyết nguyên nhân, không gây tổn hại lan rộng.","tip":"Xác định hành vi chịu trách nhiệm và tránh quy lỗi cho người không liên quan."}],"31":[{"position":1,"title":"Cảm nhận chớm nở","text":"Sự cảm ứng ở ngón chân gợi một động lòng còn sớm, chưa đủ nói lên cả mối quan hệ.","tip":"Quan sát thêm thay vì vội hành động theo một tín hiệu nhỏ."},{"position":2,"title":"Đừng vội nhúc nhích theo cảm xúc","text":"Cảm ứng ở bắp chân gợi lực thúc đẩy muốn đi; ở yên một nhịp giúp tự chủ hơn.","tip":"Dành thời gian nhận rõ cảm xúc trước khi gửi một lời quyết định."},{"position":3,"title":"Giữ quyền chọn hướng đi","text":"Cảm ứng ở đùi cùng sự chạy theo gợi việc để người khác kéo mình hơn là tự cân nhắc.","tip":"Hỏi điều mình thực sự muốn trước khi nhận lời theo cùng."},{"position":4,"title":"Kết nối bằng sự nhất quán","text":"Tâm ý qua lại gợi mong muốn được người khác đáp lại, nhưng lo nghĩ quá mức dễ làm mất tự nhiên.","tip":"Nói thật nhu cầu và cho đối phương khoảng tự do phản hồi."},{"position":5,"title":"Giữ khoảng lặng giữa kích thích","text":"Sự cảm ứng ở lưng gợi phần ít chuyển động, giúp không bị mọi tác động cuốn đi.","tip":"Giữ một khoảng cách đủ để nhìn điều đang diễn ra rõ hơn."},{"position":6,"title":"Để lời nói đi cùng sự thành thực","text":"Cảm ứng ở má và lưỡi gợi sức tác động của lời, đồng thời nhắc giới hạn của nói suông.","tip":"Chọn lời rõ ràng và chứng minh bằng một hành động phù hợp."}],"32":[{"position":1,"title":"Đừng đòi bền sâu ngay từ đầu","text":"Đào quá sâu để tìm sự bền gợi yêu cầu vượt nền tảng hiện có.","tip":"Xây một cam kết nhỏ trước khi đòi hỏi kết nối lâu dài."},{"position":2,"title":"Giữ nhịp để bớt hối tiếc","text":"Lời hối tiếc tiêu tan gợi sự điều chỉnh về mức vừa phải trong một quá trình cần bền.","tip":"Giữ việc cốt lõi đều đặn, tránh đổi hướng vì mỗi trở ngại nhỏ."},{"position":3,"title":"Nhất quán với điều mình coi trọng","text":"Đức không bền gợi sự thay đổi thất thường làm giảm tin cậy.","tip":"Chọn một nguyên tắc và áp dụng cả khi không thuận tiện."},{"position":4,"title":"Kiểm lại nơi đang tìm kết quả","text":"Ra đồng mà không có chim gợi sự bền bỉ đặt vào sai đối tượng hoặc sai địa điểm.","tip":"Kiểm giả định về cơ hội trước khi tăng công sức thêm."},{"position":5,"title":"Bền lòng cần hợp vai trò","text":"Lời cổ phân vai nam nữ gợi khác biệt trách nhiệm; không dùng để quy định ai phải phục tùng ai.","tip":"Chọn sự nhất quán phù hợp trách nhiệm thực, đồng thời biết điều chỉnh."},{"position":6,"title":"Đừng biến bền bỉ thành xao động","text":"Sự rung động kéo dài gợi đổi việc liên tục mà vẫn gọi là kiên trì.","tip":"Giảm các phản ứng nhất thời và giữ một nhịp làm việc rõ ràng."}],"33":[{"position":1,"title":"Rút lui khi đã ở cuối đoàn","text":"Ở đuôi cuộc rút gợi thế khó đổi hướng nhanh; hấp tấp tiến thêm có thể làm kẹt hơn.","tip":"Giữ an toàn và tìm đường lui trong phạm vi còn kiểm soát."},{"position":2,"title":"Xem điều mình đang giữ chặt","text":"Da bò vàng buộc chắc gợi một cam kết hoặc nguyên tắc khó cởi bỏ.","tip":"Phân biệt giá trị đáng giữ với ràng buộc chỉ vì sợ thay đổi."},{"position":3,"title":"Tháo bớt vướng víu trước khi lùi","text":"Rút mà còn bị níu gợi việc muốn rời một tình thế nhưng vẫn mang nhiều phụ thuộc.","tip":"Giải quyết nghĩa vụ thiết yếu và thu hẹp phần còn phải ôm."},{"position":4,"title":"Buông điều mình thích khi cần","text":"Có thể rời việc đáng thích gợi tự chủ trước sự quyến luyến.","tip":"So điều đang yêu thích với mục tiêu dài hạn rồi chọn khoảng cách phù hợp."},{"position":5,"title":"Rút lui có phẩm cách","text":"Sự rút tốt đẹp gợi cách khép việc đúng mực, không cần phá quan hệ để chứng minh mình đúng.","tip":"Bàn giao rõ ràng và nói lý do với thái độ tôn trọng."},{"position":6,"title":"Rời đi khi đã nhẹ gánh","text":"Sự rút lui rộng rãi gợi tự do hơn khi không còn mắc vào tranh chấp hay quyến luyến.","tip":"Dùng khoảng trống mới để phục hồi và xây hướng phù hợp hơn."}],"34":[{"position":1,"title":"Đừng chỉ mạnh ở bước lao tới","text":"Sức mạnh dồn xuống ngón chân gợi khí thế muốn tiến trước khi hiểu giới hạn.","tip":"Kiểm điểm tựa và hậu quả trước một hành động bốc đồng."},{"position":2,"title":"Giữ sức trong nguyên tắc","text":"Lời giữ chính gợi khả năng dùng sức đúng mức khi không bị ham thắng kéo đi.","tip":"Chọn cách làm phù hợp trách nhiệm thay vì chứng tỏ mình mạnh."},{"position":3,"title":"Đừng húc mãi vào hàng rào","text":"Dê đực mắc sừng gợi sức mạnh dùng sai chỗ thành ràng buộc cho chính mình.","tip":"Đổi phương án khi đối đầu trực diện liên tục không có kết quả."},{"position":4,"title":"Tiến khi đường đã mở","text":"Hàng rào mở và xe có chỗ đỡ vững gợi điều kiện để tiến. Sức mạnh cần đi cùng sự đúng đắn và chừng mực, thay vì cố dùng hết sức.","tip":"Giữ nguyên tắc và kiểm phần nâng đỡ trước khi tận dụng thuận lợi."},{"position":5,"title":"Buông cuộc hơn thua không cần thiết","text":"Mất con dê mà không hối tiếc gợi bỏ sức cứng hoặc điều đang cố giữ có thể làm nhẹ việc.","tip":"Bỏ một tranh chấp không còn phục vụ mục tiêu chính."},{"position":6,"title":"Thoát thế không tiến không lui","text":"Dê mắc rào không thể tiến hoặc lùi gợi cần nhìn nhận khó khăn trước khi có lối đổi.","tip":"Ngừng thúc thêm sức, tìm người hỗ trợ tháo nút mắc."}],"35":[{"position":1,"title":"Giữ nhịp khi tiến rồi bị cản","text":"Muốn tiến mà bị đẩy lùi gợi bước khởi đầu chưa được tin, cần lòng rộng và sự bền hơn là cố ép.","tip":"Chứng minh bằng việc nhỏ và để người khác có thời gian quan sát."},{"position":2,"title":"Nhận nâng đỡ khi còn lo","text":"Tiến mà vẫn buồn, rồi nhận điều lành từ bậc lớn gợi hỗ trợ có thể đến qua người dìu dắt.","tip":"Trao đổi khó khăn cụ thể với người có kinh nghiệm và thiện chí."},{"position":3,"title":"Xây sự đồng thuận","text":"Mọi người tin nhận gợi tiến bộ trở nên vững khi có sự chấp thuận thực chất của tập thể.","tip":"Xác nhận các bên đã hiểu và đồng ý với hướng đi."},{"position":4,"title":"Đừng tiến như loài gặm nhấm","text":"Hình tượng con chuột gợi cách giành phần bằng lén lút hay chỉ thu lợi cho mình.","tip":"Minh bạch cách đạt kết quả và sửa hành vi làm giảm tin cậy."},{"position":5,"title":"Bớt bận được mất để làm đúng việc","text":"Bớt lo được mất gợi việc thôi tính công hay lợi trước mắt để làm phần việc có ích. Sự rộng lòng vẫn cần đi cùng cách làm đúng đắn.","tip":"Chọn một tiêu chuẩn giá trị chung và kiểm việc mình làm theo tiêu chuẩn ấy."},{"position":6,"title":"Dùng sức mạnh trong phạm vi có trách nhiệm","text":"Tiến bằng sừng và chỉnh nội bộ gợi lúc cứng rắn chỉ nên có giới hạn, không thành nếp cưỡng ép.","tip":"Nêu việc cần sửa trong nhóm mình và chọn mức can thiệp vừa đủ."}],"36":[{"position":1,"title":"Giữ ánh sáng khi phải thu cánh","text":"Chim bay rủ cánh và người đi thiếu ăn gợi chặng khó cần tiết chế sự bộc lộ và giữ nguồn sống.","tip":"Giảm việc phô bày, chăm điều thiết yếu và giữ một đường lui."},{"position":2,"title":"Tìm phương tiện để thoát chỗ khó","text":"Bị thương ở đùi và nhờ ngựa khỏe cứu gợi tầm quan trọng của trợ lực khi khó tự xoay xở.","tip":"Nhờ người đáng tin và chọn cách hỗ trợ phù hợp mức khó hiện có."},{"position":3,"title":"Tháo đầu mối, tránh nóng vội","text":"Cuộc săn tìm được đầu mối lớn gợi cơ hội chấn chỉnh gốc vấn đề nhưng không thể sửa hết trong một nhịp.","tip":"Xác định nguyên nhân chính và chia tiến trình thay đổi thành từng bước."},{"position":4,"title":"Hiểu bên trong để chọn rời đi","text":"Đi vào bụng trái rồi bước khỏi sân gợi nhận rõ động cơ của một tình thế trước khi thoát ra.","tip":"Kiểm điều mình đã hiểu và rời khỏi phần tham gia gây hại."},{"position":5,"title":"Giữ nguyên tắc trong môi trường bất lợi","text":"Hình tượng Cơ Tử gợi bảo toàn phẩm giá và sự sáng suốt khi chưa thể biểu lộ thẳng thắn.","tip":"Giữ một nguyên tắc cốt lõi cùng cách tự bảo vệ phù hợp."},{"position":6,"title":"Đừng để vị thế che mất điều sáng","text":"Từ lên trời đến rơi xuống đất gợi sự đảo chiều khi quyền lực làm mất tự xét.","tip":"Mở kênh phản hồi và kiểm tác động của quyền mình đang có."}],"37":[{"position":1,"title":"Đặt nếp chung từ sớm","text":"Giữ phép nhà ngay đầu gợi lợi ích của ranh giới rõ trước khi bất đồng thành thói quen.","tip":"Thỏa thuận giờ giấc, phần việc và cách giải quyết mâu thuẫn."},{"position":2,"title":"Chăm nền sinh hoạt mỗi ngày","text":"Hình ảnh lo việc ăn uống trong nhà gợi giá trị của công việc nuôi dưỡng thầm lặng, không ràng trách nhiệm theo giới.","tip":"Chia việc nhà công bằng và giữ những nếp thiết yếu."},{"position":3,"title":"Cân bằng nghiêm và dễ dãi","text":"Nhà quá nghiêm có căng thẳng, quá đùa dễ mất nếp gợi nhu cầu đặt giới hạn có tình.","tip":"Giải thích nguyên tắc và nghe nhu cầu của từng thành viên."},{"position":4,"title":"Góp phần làm nhà đủ đầy","text":"Làm giàu cho nhà gợi chăm nguồn lực chung và sự ổn định trong phạm vi gia đình.","tip":"Cùng lập kế hoạch chi tiêu, công sức và khoản dự phòng vừa sức."},{"position":5,"title":"Đến với gia đình bằng sự tin cậy","text":"Người đứng đầu đến nhà mà bớt lo gợi ảnh hưởng tích cực khi có sự gần gũi và tôn trọng.","tip":"Dành thời gian lắng nghe thay vì chỉ điều hành việc trong nhà."},{"position":6,"title":"Uy tín từ nếp sống nhất quán","text":"Lòng thành và sự nghiêm trang gợi cách làm gương tạo sức nặng hơn lời yêu cầu.","tip":"Giữ lời hứa và thực hiện nguyên tắc mình mong người khác theo."}],"38":[{"position":1,"title":"Để khoảng cách có lúc tự điều chỉnh","text":"Ngựa mất rồi về và gặp người khó chịu gợi không cần đuổi theo hay né tránh mọi khác biệt.","tip":"Giữ bình tĩnh, quan sát thực tế và giao tiếp có giới hạn."},{"position":2,"title":"Tìm chỗ gặp không quá hình thức","text":"Gặp người chủ nơi ngõ gợi một kênh trao đổi đời thường có thể giúp tháo khoảng cách.","tip":"Chọn thời điểm và nơi nói chuyện khiến hai bên dễ mở lòng."},{"position":3,"title":"Đừng kết luận từ khởi đầu rối","text":"Xe bị kéo, bò bị ngăn và hình tượng tổn hại gợi trở lực chồng nhau; chưa thuận đầu không quyết định đoạn cuối.","tip":"Gỡ từng đầu mối và tránh quy trách nhiệm khi thông tin còn rối."},{"position":4,"title":"Tìm người có thể cùng tin","text":"Một mình giữa khác biệt rồi gặp người đáng tin gợi hợp tác có thể bắt đầu dù hoàn cảnh chưa dễ.","tip":"Trao đổi một việc nhỏ có thể kiểm chứng để xây lại tin cậy."},{"position":5,"title":"Tháo ngăn cách gần mình","text":"Người cùng nhóm cắn qua lớp mềm gợi một rào cản quan hệ có thể không cứng như tưởng.","tip":"Nói thẳng một hiểu lầm với thái độ sẵn lòng lắng nghe."},{"position":6,"title":"Kiểm hình ảnh đáng sợ trước khi phản ứng","text":"Lợn bùn, xe quỷ rồi nhận ra người cầu kết nối gợi nghi kỵ có thể khiến mình nhìn sai ý định.","tip":"Dừng phản ứng phòng thủ và xác minh bằng dữ kiện trực tiếp."}],"39":[{"position":1,"title":"Lùi để nhận ra cách đi khác","text":"Đi gặp khó, trở lại được ghi nhận gợi một bước lui có suy xét có thể hữu ích hơn cố tiến.","tip":"Xem lại điều kiện trước khi thử lại cùng một cách."},{"position":2,"title":"Phân biệt trách nhiệm với lợi riêng","text":"Người bề tôi gặp khó vì việc chung gợi gánh nặng được nhận vì nghĩa vụ, không chỉ vì bản thân.","tip":"Xác định phần trách nhiệm chính đáng và người cần cùng hỗ trợ."},{"position":3,"title":"Trở về chỉnh kế hoạch","text":"Tiến khó nên quay lại gợi việc rút về nền đã biết để thay đổi cách tiếp cận.","tip":"Sửa một giả định quan trọng trước khi ra quyết định tiếp."},{"position":4,"title":"Tìm liên kết khi đường bị chặn","text":"Đi khó rồi trở lại để nối nhau gợi sức của đồng hành khi một người không đủ xoay xở.","tip":"Tìm người có năng lực bổ sung và chia rõ phần việc."},{"position":5,"title":"Đón bạn bè trong thử thách lớn","text":"Khó lớn mà bạn tới gợi sự trợ giúp được nuôi bởi quan hệ tin cậy trước đó.","tip":"Nói rõ việc cần giúp và chủ động phối hợp thay vì chịu một mình."},{"position":6,"title":"Lùi để có góc nhìn rộng","text":"Tiến gặp khó, trở về được điều lớn và gặp người sáng gợi giá trị của tư vấn đúng lúc.","tip":"Xin ý kiến người có kinh nghiệm trước khi chọn lộ trình mới."}],"40":[{"position":1,"title":"Giữ khoảng nhẹ vừa được mở","text":"Lời không lỗi gợi một thời điểm có thể thôi tự buộc mình vào căng thẳng cũ.","tip":"Khép việc đã giải quyết và không khơi lại tranh chấp vô ích."},{"position":2,"title":"Tìm đúng điều gây rối","text":"Săn được ba cáo và mũi tên vàng gợi việc bóc tách nguồn nhiễu bằng sự ngay thẳng.","tip":"Kiểm chứng một nghi ngờ và xử lý nguyên nhân có bằng chứng."},{"position":3,"title":"Đừng phô điều vượt nền bảo vệ","text":"Mang gánh mà cưỡi xe gợi sự không tương xứng dễ thu hút rắc rối.","tip":"Kiểm cách thể hiện nguồn lực và giảm điểm phô trương không cần thiết."},{"position":4,"title":"Tháo một ràng buộc để đón bạn tốt","text":"Giải phóng ngón chân gợi bỏ điều nhỏ đang níu bước và mở chỗ cho kết nối tin cậy.","tip":"Dừng một cam kết làm mình khó phối hợp với người phù hợp."},{"position":5,"title":"Giải thoát bằng hành động có sức thuyết phục","text":"Người có trách nhiệm tháo nút cho người khác gợi sự thay đổi cần thể hiện bằng việc làm.","tip":"Thực hiện một bước công bằng để người hoài nghi có thể kiểm thấy."},{"position":6,"title":"Xử lý điểm mắc ở nơi cao","text":"Bắn chim cắt trên tường cao gợi chướng ngại rõ cần năng lực, công cụ và thời điểm phù hợp.","tip":"Chuẩn bị đủ điều kiện rồi xử lý đúng một nút thắt chính."}],"41":[{"position":1,"title":"Giúp nhanh nhưng trong mức có thể","text":"Ngừng việc riêng để kịp giúp người, rồi cân nhắc mức đóng góp, gợi sự tương trợ đúng lúc và vừa khả năng.","tip":"Xác nhận điều người kia cần; chọn phần mình giúp được mà vẫn giữ các trách nhiệm thiết yếu."},{"position":2,"title":"Giữ nền mình để giúp bền","text":"Không giảm mà tăng ích gợi hỗ trợ không nhất thiết bằng tự hy sinh phần thiết yếu.","tip":"Chọn chia kiến thức, thời gian hoặc cách tổ chức thay vì ôm hết."},{"position":3,"title":"Điều chỉnh đội hình hợp tác","text":"Ba người giảm một, một người gặp bạn gợi chất lượng phối hợp có lúc cần đổi cấu trúc.","tip":"Làm rõ mục tiêu và vai trò thay vì giữ nhóm chỉ vì thói quen."},{"position":4,"title":"Bớt điều đang làm khó mình","text":"Giảm chỗ tật xấu gợi một thay đổi nhỏ đúng gốc có thể làm nhẹ tình thế.","tip":"Chọn một thói quen gây vướng và thay bằng hành động dễ duy trì."},{"position":5,"title":"Đón sự hỗ trợ đáng tin","text":"Mai rùa quý và điều được thêm gợi một trợ lực có giá trị khi mình còn sẵn lòng tiếp nhận.","tip":"Kiểm thiện ý, điều kiện và dùng hỗ trợ đúng mục đích."},{"position":6,"title":"Tạo ích lợi không làm ai cạn kiệt","text":"Không giảm mà thêm, có người cùng theo gợi cách phân bổ nguồn lực giúp cả tập thể.","tip":"Thiết kế phần đóng góp công bằng và kiểm người nào đang chịu quá nhiều."}],"42":[{"position":1,"title":"Dùng thuận lợi làm việc đáng kể","text":"Được thêm để làm việc lớn gợi trách nhiệm biến nguồn lực mới thành giá trị thật.","tip":"Chọn một mục tiêu có ích và kiểm năng lực thực hiện đến cùng."},{"position":2,"title":"Giữ lòng bền khi được nâng đỡ","text":"Sự hỗ trợ quý cùng việc giữ lâu dài gợi thuận lợi cần nền ứng xử nhất quán.","tip":"Tiếp nhận giúp đỡ minh bạch và giữ đúng cam kết đã thống nhất."},{"position":3,"title":"Biến việc khó thành dịp giúp nhau","text":"Đem lợi ích vào lúc có biến cố gợi dùng nguồn lực cho điều cần thiết, đi cùng sự thành thực.","tip":"Trao đổi rõ với người chịu trách nhiệm và hỗ trợ đúng nơi cấp thiết."},{"position":4,"title":"Thay đổi lớn cần điểm tựa chung","text":"Việc dời nước sau khi báo người đứng đầu gợi sự chuyển đổi cần đồng thuận và nơi nương tựa.","tip":"Chuẩn bị người, nguồn lực và thông tin trước một cuộc chuyển lớn."},{"position":5,"title":"Cho đi từ lòng thành","text":"Tấm lòng muốn làm ích gợi giá trị của sự quan tâm không đòi hỏi đổi trả ngay.","tip":"Hỏi điều người nhận cần và giúp trong phạm vi bền được."},{"position":6,"title":"Đừng chỉ mong được thêm","text":"Không ai thêm mà còn phản ứng lại gợi hệ quả khi lòng cầu lợi đi cùng ý định thất thường.","tip":"Giữ cam kết và xem mình đã góp gì cho quan hệ chung."}],"43":[{"position":1,"title":"Đừng quyết ở mũi chân","text":"Mạnh ở bước lao tới mà chưa thắng gợi quyết đoán thiếu nền dễ thành sơ suất.","tip":"Kiểm thông tin và phương án trước khi công bố một quyết định khó rút."},{"position":2,"title":"Chuẩn bị khi việc chưa xảy ra","text":"Cảnh báo lúc chiều tối gợi tỉnh thức và dự phòng có thể giúp bình tĩnh trước bất ngờ.","tip":"Thống nhất một kênh liên lạc và phương án ứng phó vừa sức."},{"position":3,"title":"Vững quyết định mà không cứng vẻ ngoài","text":"Nét mặt gân guốc và người đi riêng gặp mưa gợi lựa chọn đúng có thể khiến người khác chưa hiểu.","tip":"Giải thích lý do, giữ thái độ điềm tĩnh và chấp nhận thời gian kiểm chứng."},{"position":4,"title":"Nghe lời nhắc khi bước đi khó","text":"Đi không thuận và được khuyên dắt dê gợi việc tự ái có thể cản tiếp nhận một cách đi mềm hơn.","tip":"Thử lời góp ý cụ thể trước khi bác bỏ vì không hợp ý."},{"position":5,"title":"Loại bỏ điều dai dẳng có chừng mực","text":"Cây mọc mạnh cần quyết bỏ gợi việc sửa nếp bám sâu nên đi cùng sự công bằng, không quá tay.","tip":"Xác định hành vi cần dừng và nguyên tắc áp dụng cho mọi người."},{"position":6,"title":"Đừng im lặng trước điểm còn sót","text":"Không còn tiếng cảnh báo gợi sự chủ quan vào cuối chặng quyết bỏ điều cũ.","tip":"Kiểm lại điều chưa xử lý và giữ kênh phản hồi hoạt động."}],"44":[{"position":1,"title":"Giữ chốt khi ảnh hưởng mới tới","text":"Chốt kim loại và con lợn non nôn nóng gợi điều mới nhỏ vẫn có thể tăng sức nếu không đặt giới hạn.","tip":"Đặt ranh giới sớm cho một tác động đang kéo mình khỏi nếp đúng."},{"position":2,"title":"Giữ gìn điều vừa được nhận","text":"Có cá trong bọc gợi một nguồn lực hay kết nối còn cần bảo vệ, chưa nên đem phân tán rộng.","tip":"Chăm mối liên hệ trực tiếp trước khi đưa thêm người vào."},{"position":3,"title":"Đi chậm khi đang khó ngồi yên","text":"Da mông tổn thương và bước chậm gợi sự khó chịu thúc mình nhưng chưa hẳn phải hành động gấp.","tip":"Giảm nhịp và xử lý nguồn gây bất an trước quyết định mới."},{"position":4,"title":"Xem điều đã làm mất kết nối","text":"Bọc không có cá gợi nguồn lực hoặc quan hệ không còn ở nơi mình tưởng.","tip":"Kiểm thực trạng và xây lại điều kiện để người khác muốn hợp tác."},{"position":5,"title":"Nuôi điều tốt một cách kín đáo","text":"Che quả dưa bằng cành và giữ vẻ đẹp bên trong gợi bảo vệ tiềm năng mà chưa cần phô bày.","tip":"Chăm chất lượng và để kết quả chín theo điều kiện thực."},{"position":6,"title":"Bớt dùng sự cứng rắn để gặp nhau","text":"Gặp bằng sừng gợi va chạm vì góc cạnh hoặc tự giữ mình quá xa.","tip":"Điều chỉnh cách tiếp xúc và chấp nhận khác biệt không thể xóa ngay."}],"45":[{"position":1,"title":"Khôi phục lòng tin bị đứt quãng","text":"Có lòng mà không đến cuối, rồi gọi nhau lại gợi một nhóm rối vẫn có thể nối bằng trao đổi chân thành.","tip":"Nói rõ điều đã đổi và thống nhất lại cam kết nhỏ."},{"position":2,"title":"Đón lời mời có thành ý","text":"Được dẫn vào cuộc hội tụ cùng lễ đơn sơ gợi liên kết không cần hình thức lớn để có giá trị.","tip":"Chấp nhận sự hợp tác phù hợp và giữ cách làm rõ ràng."},{"position":3,"title":"Tìm chỗ tham gia dù còn ngại","text":"Muốn tụ mà thở than gợi cảm giác đứng ngoài; bước tới có thể còn ngượng nhưng không nhất thiết sai.","tip":"Chủ động hỏi mình có thể góp gì cho nhóm."},{"position":4,"title":"Làm tốt vai trò trong cuộc hội tụ","text":"Lời tốt lớn gợi điều kiện thuận của sự cùng đến khi có nền tảng phù hợp.","tip":"Củng cố cách phối hợp để thuận lợi không chỉ nằm ở số người đông."},{"position":5,"title":"Vị trí không tự tạo lòng tin","text":"Đã có chỗ đứng mà chưa được tin gợi quyền hạn cần thời gian và cách hành xử để được nhận.","tip":"Giữ việc đã hứa và để người khác kiểm được kết quả."},{"position":6,"title":"Cho nỗi buồn một lối bày tỏ","text":"Nước mắt ở cuối cuộc hội tụ gợi cảm giác chưa được kết nối hoặc chia sẻ hết.","tip":"Nói điều đang hụt hẫng với người tin cậy, không tự ép phải vui."}],"46":[{"position":1,"title":"Tiến lên nhờ được tin nhận","text":"Sự lên cao có đồng thuận gợi khởi đầu thuận khi năng lực và lòng tin cùng hỗ trợ.","tip":"Đón nhận trách nhiệm vừa sức và giữ liên lạc với người hỗ trợ."},{"position":2,"title":"Giữ thành ý trong điều giản dị","text":"Lễ nhỏ mà có lòng gợi việc tiến lên không cần dùng hình thức để bù sự thiếu chân thành.","tip":"Làm một cam kết nhỏ thật tốt thay vì nói điều quá lớn."},{"position":3,"title":"Nhìn cơ hội nơi còn khoảng trống","text":"Đi lên thành trống gợi ít vật cản, nhưng khoảng rộng cũng cần mục tiêu để không đi vô hướng.","tip":"Xác định điều muốn xây trước khi nhận mọi cơ hội đang mở."},{"position":4,"title":"Tiến nhờ tôn trọng nền tảng","text":"Việc cúng trên núi Kỳ gợi hành động nối giá trị hiện tại với truyền thống hoặc cộng đồng nâng đỡ.","tip":"Ghi nhận nền đã có và làm rõ điều muốn tiếp nối."},{"position":5,"title":"Lên từng bậc vững chắc","text":"Bước lên thềm gợi tiến bộ có trật tự nhờ giữ một hướng và hoàn thành từng mức.","tip":"Chốt điều kiện hoàn thành mỗi bước trước khi nhận bước kế."},{"position":6,"title":"Đừng mải tiến trong bóng tối","text":"Cứ lên khi không còn nhìn rõ gợi sự bền bỉ dễ thành cố chấp nếu mất tự xét.","tip":"Kiểm hướng đi thường xuyên, chỉ duy trì điều còn có lý do vững."}],"47":[{"position":1,"title":"Tìm lối ra khỏi sự cô lập","text":"Ngồi trên gốc cây rồi vào thung sâu gợi hoàn cảnh bí bách dễ khiến mình thu hẹp kết nối.","tip":"Giữ liên hệ với người tin cậy và tìm một nguồn hỗ trợ thực."},{"position":2,"title":"Đừng lấy sự đủ đầy che chỗ khó","text":"Bị vướng giữa ăn uống và dấu hiệu trợ giúp gợi nhu cầu phân biệt tiện nghi với điều thực sự đang thiếu.","tip":"Nêu rõ nhu cầu và tiếp nhận hỗ trợ trước khi vội đi xa."},{"position":3,"title":"Đừng tựa vào nơi làm đau mình","text":"Đá và gai gợi một chỗ nương không phù hợp, khiến trở về cũng khó nhận được kết nối.","tip":"Đổi điểm tựa và nói rõ điều mình cần để được giúp đúng."},{"position":4,"title":"Gỡ điều níu bước khi giúp nhau","text":"Sự trợ giúp đến chậm và hình ảnh xe cản lối gợi một kết nối còn vướng trở ngại. Có thể xem điều gì đang ngăn hai bên đến với nhau, thay vì chỉ cố chờ.","tip":"Làm rõ bên nào cần giúp, vướng ở đâu và một bước nhỏ có thể tháo gỡ."},{"position":5,"title":"Chờ sự tháo gỡ từng phần","text":"Hình tượng bị hạn chế rồi dần được nới gợi việc khó có thể cần tiến trình chậm và sự kết nối.","tip":"Theo dõi từng cải thiện nhỏ và giữ trao đổi với người hỗ trợ."},{"position":6,"title":"Dám rời dây leo vướng víu","text":"Bị dây leo trói, sợ động rồi nhận ra hối tiếc gợi tự sửa cách nhìn có thể mở bước đi.","tip":"Nhận ra nỗi sợ nào đang giữ mình và thử bước tháo vừa sức."}],"48":[{"position":1,"title":"Làm sạch nguồn đã bị bỏ quên","text":"Giếng bùn không ai dùng gợi nguồn lực xuống cấp vì thiếu chăm sóc.","tip":"Kiểm một nền tảng cũ và sửa trước khi kỳ vọng nó phục vụ."},{"position":2,"title":"Sửa dụng cụ giữ nguồn lực","text":"Nước chỉ tới cá nhỏ và bình rò gợi khả năng có nguồn nhưng không đưa tới nơi cần.","tip":"Tìm điểm rò trong quy trình hoặc công cụ và khắc phục."},{"position":3,"title":"Đưa nguồn tốt tới người cần","text":"Giếng đã vét mà chưa ai uống gợi giá trị chưa được tiếp cận do thiếu kênh sử dụng.","tip":"Làm rõ cách tiếp cận và người có thể dùng điều mình đã chuẩn bị."},{"position":4,"title":"Chấp nhận thời gian bảo trì","text":"Xây thành giếng gợi có lúc chưa thu kết quả ngay vì đang gia cố độ bền.","tip":"Dành thời gian sửa nền và thông báo rõ giai đoạn bảo trì."},{"position":5,"title":"Giữ chất lượng của nguồn chung","text":"Nước giếng trong mát được dùng gợi giá trị từ chất lượng thực và khả năng đáp ứng nhu cầu.","tip":"Duy trì tiêu chuẩn và kiểm việc sử dụng có bền lâu hay không."},{"position":6,"title":"Mở nguồn với sự tin cậy","text":"Giếng không che kín gợi chia sẻ khả năng tiếp cận khi nguồn được giữ tốt.","tip":"Đặt cách dùng công bằng và trách nhiệm chăm nguồn chung."}],"49":[{"position":1,"title":"Giữ chắc trước lúc đổi","text":"Da bò vàng buộc vững gợi lúc điều kiện chưa chín cần giữ nền và hạn chế xáo động.","tip":"Làm rõ điều chưa nên thay trong khi chuẩn bị cải tiến."},{"position":2,"title":"Đổi khi thời điểm đã tới","text":"Đến ngày mới thay gợi sự chuyển đổi cần quá trình chuẩn bị thay vì phản ứng tức thời.","tip":"Xác nhận người, nguồn lực và lý do trước khi triển khai."},{"position":3,"title":"Tạo đồng thuận qua nhiều lần bàn","text":"Lời cải cách được xét nhiều lần gợi lòng tin cần đối thoại và kiểm kỹ trước việc lớn.","tip":"Ghi nhận phản biện rồi chỉnh đề xuất trước khi thực hiện."},{"position":4,"title":"Thay đổi trên nền tin cậy","text":"Có lòng tin rồi đổi mệnh gợi khả năng chuyển quy tắc khi người tham gia đã hiểu lý do.","tip":"Công bố điều thay, người chịu trách nhiệm và cách đánh giá kết quả."},{"position":5,"title":"Để thay đổi hiện thành dấu rõ","text":"Hổ đổi vằn gợi biến chuyển lớn có thể được nhận ra từ cách làm và kết quả.","tip":"Nêu minh chứng cụ thể thay vì chỉ tuyên bố đã đổi mới."},{"position":6,"title":"Ổn định sau cuộc thay đổi","text":"Báo đổi đốm và người đổi vẻ mặt gợi thay đổi có mức sâu khác nhau; tiến thêm dễ làm xáo động.","tip":"Củng cố hành vi mới và kiểm điều gì mới đổi ở bề ngoài."}],"50":[{"position":1,"title":"Dọn cũ để chuẩn bị nuôi mới","text":"Vạc lật cho chất bẩn ra gợi việc đảo một nếp cũ có thể hữu ích khi nhằm làm sạch nền.","tip":"Loại điều không còn dùng rồi xây cách sử dụng mới phù hợp."},{"position":2,"title":"Chăm điều thực có trong vạc","text":"Vạc có thực phẩm gợi giá trị nằm ở phần có thể nuôi dưỡng, không cần tranh với người đang đối nghịch.","tip":"Giữ chất lượng việc mình làm và tránh bị kéo vào hơn thua."},{"position":3,"title":"Sửa chỗ đưa giá trị ra ngoài","text":"Tai vạc thay đổi khiến thức ngon chưa dùng được gợi khả năng tốt bị nghẽn ở khâu tiếp cận.","tip":"Tìm điểm liên kết bị tắc và thử một kênh phối hợp khác."},{"position":4,"title":"Đừng giao tải vượt chân đỡ","text":"Vạc gãy chân làm đổ phần ăn chung gợi trách nhiệm lớn nhưng chỗ nâng đỡ chưa đủ. Cần xem lại năng lực, cách giao việc và phần việc có thể ảnh hưởng người khác.","tip":"Kiểm sức chịu tải, bổ sung người hỗ trợ hoặc thu hẹp cam kết trước khi nhận thêm."},{"position":5,"title":"Giữ quai nâng vững và cân","text":"Tai vạc vàng, đòn kim loại gợi sự kết hợp giữa chất lượng bên trong và phương tiện đưa vào dùng.","tip":"Kiểm cả nội dung lẫn cách bàn giao cho người sử dụng."},{"position":6,"title":"Hoàn thiện cách nâng giá trị","text":"Đòn ngọc gợi chặng hoàn thiện khi sự bền chắc và tinh tế hỗ trợ nhau.","tip":"Giữ tiêu chuẩn và chăm trải nghiệm người dùng khi việc đã vận hành tốt."}],"51":[{"position":1,"title":"Bình tâm sau cú giật mình","text":"Sấm đến làm run rồi có tiếng cười gợi một phản ứng sợ hãi có thể lắng khi đã kiểm rõ tình hình.","tip":"Dừng một nhịp, kiểm điều thiết yếu rồi mới phản hồi."},{"position":2,"title":"Giữ an toàn hơn đuổi theo phần mất","text":"Sấm dữ, của rơi và lên gò cao gợi ưu tiên chỗ đứng an toàn trước việc cố lấy lại mọi thứ.","tip":"Giảm nguy cơ trước, xử lý tổn thất bằng dữ kiện khi tình hình yên hơn."},{"position":3,"title":"Đổi sợ hãi thành hành động vừa sức","text":"Bàng hoàng vì sấm rồi chuyển động gợi khả năng lấy lại chủ động thay vì đứng lặng mãi.","tip":"Chọn một việc nhỏ giúp ổn định tình hình ngay lúc này."},{"position":4,"title":"Thoát khỏi chỗ lún giữa biến động","text":"Sấm mắc trong bùn gợi phản ứng thiếu điểm tựa khiến mình càng vùng càng khó.","tip":"Tìm nguyên nhân trì trệ và đổi phương tiện hỗ trợ trước khi thúc tiếp."},{"position":5,"title":"Giữ việc cốt lõi qua nhiều đợt động","text":"Sấm qua lại nguy mà còn việc phải giữ gợi sự bền tỉnh trong hoàn cảnh không ổn định.","tip":"Xác định điều thiết yếu và phân công để không bỏ sót."},{"position":6,"title":"Nhận tín hiệu gần mình trước khi lan rộng","text":"Run rẩy nhìn quanh, sấm ở nhà bên gợi cảnh báo có thể học từ việc chưa trực tiếp chạm tới mình.","tip":"Rà sự chuẩn bị và tránh lời quyết định trong lúc hoảng."}],"52":[{"position":1,"title":"Dừng từ ý định mới chớm","text":"Giữ ngón chân gợi khả năng dừng một bước khi nó chưa thành đà khó đổi.","tip":"Đặt giới hạn cho hành động mình biết cần tránh từ đầu."},{"position":2,"title":"Thấy điều không vừa khi khó tự dừng","text":"Giữ bắp chân mà không cứu được phần theo sau gợi một sự lệ thuộc khiến lòng khó yên.","tip":"Làm rõ điều mình kiểm soát được và đề nghị thay đổi chỗ ràng buộc."},{"position":3,"title":"Đừng ép mình đứng yên đến căng cứng","text":"Hình ảnh giữ chặt chỗ chuyển động đến mức trên dưới chia lìa gợi sự cố dừng đã thành bế tắc. Cần tìm cách tự chế có thể duy trì, tránh ép mình đến căng cứng.","tip":"Giảm một quy tắc tự ép không còn hữu ích; dành khoảng nghỉ rồi điều chỉnh cách làm."},{"position":4,"title":"Giữ thân mình khỏi phản ứng thừa","text":"Dừng ở thân gợi tự chủ trong phạm vi hành vi của chính mình thay vì cố kiểm người khác.","tip":"Bớt một hành động không cần thiết trước tình huống đang kích thích mình."},{"position":5,"title":"Dừng lời để nói có trật tự","text":"Giữ hàm và lời có thứ tự gợi giá trị của sự cân nhắc trước khi phát ngôn.","tip":"Nói điều đã kiểm rõ và chừa thời gian nghe người khác."},{"position":6,"title":"Nuôi sự tĩnh lặng có chiều sâu","text":"Sự dừng đôn hậu gợi bình ổn đã thành nền, không chỉ là cố nén một lúc.","tip":"Giữ một thói quen nghỉ và tự xét có thể duy trì lâu dài."}],"53":[{"position":1,"title":"Làm quen vùng bờ mới","text":"Chim hồng đến bờ và lời lo của người trẻ gợi chặng đầu còn lạ lẫm, cần từng bước thích nghi.","tip":"Tìm hiểu điều kiện và nhận hướng dẫn trước khi đi xa hơn."},{"position":2,"title":"Dừng ở nơi có thể nuôi sức","text":"Chim tới đá vững, ăn uống vui gợi một điểm nghỉ ổn để phục hồi và kết nối.","tip":"Chăm nhịp sinh hoạt và củng cố người đồng hành trước bước kế."},{"position":3,"title":"Đừng bỏ nền bảo vệ để tiến liều","text":"Chim tới đất và hình tượng gia đình chia lìa gợi hệ quả của bước tiến làm đứt nền nâng đỡ, không dự báo sinh sản.","tip":"Bảo vệ quan hệ và điều kiện thiết yếu trước thay đổi lớn."},{"position":4,"title":"Tìm chỗ đậu phù hợp","text":"Chim lên cây có thể gặp cành bằng gợi thích nghi trong môi trường chưa hoàn toàn thuận.","tip":"Chọn một chỗ đứng vừa sức và kiểm điều kiện giữ vững nó."},{"position":5,"title":"Kiên nhẫn trước điều chậm thành","text":"Chim lên gò và hình tượng chậm sinh gợi quá trình có ngăn trở nhưng chưa nên kết luận thất bại; không dùng để đoán thai sản.","tip":"Theo dõi tiến triển bằng dữ kiện thay vì áp thời hạn tưởng tượng."},{"position":6,"title":"Để kinh nghiệm thành điều có thể trao","text":"Lông chim dùng làm nghi lễ gợi giá trị đẹp được hình thành qua một hành trình dài.","tip":"Chia sẻ điều đã học bằng cách rõ ràng và hữu ích cho người sau."}],"54":[{"position":1,"title":"Bắt đầu từ vai trò thực có","text":"Hình tượng người theo đoàn cưới và chân yếu vẫn đi gợi đóng góp trong phạm vi chưa hoàn hảo; không gán thứ bậc cho người dùng.","tip":"Làm rõ vai trò và chọn phần việc phù hợp khả năng hiện tại."},{"position":2,"title":"Giữ sự sáng trong điều kiện hạn chế","text":"Mắt yếu vẫn thấy gợi khả năng quan sát còn có giá trị dù hoàn cảnh chưa cho đầy đủ điều mong muốn.","tip":"Tập trung phần mình nhìn rõ và giữ quyền tự chủ trong lựa chọn."},{"position":3,"title":"Xem lại vị thế mình nhận","text":"Chờ kết hôn rồi trở về vai thấp hơn gợi sự không tương xứng giữa mong đợi và điều được đề nghị.","tip":"Thương lượng rõ quyền lợi, trách nhiệm và giới hạn trước khi nhận lời."},{"position":4,"title":"Chờ để có một lựa chọn phù hợp","text":"Lỡ thời hẹn rồi còn lúc đến gợi sự trì hoãn không tự nó làm mất giá trị của quyết định.","tip":"Chọn thời điểm theo điều kiện thực thay vì áp lực phải kịp người khác."},{"position":5,"title":"Giá trị không nằm ở tay áo đẹp","text":"Cuộc cưới vương thất và tay áo giản dị gợi sự chừng mực bên trong quan trọng hơn trang phục hay thứ bậc.","tip":"Đánh giá kết nối qua cách đối xử, không qua mức phô bày."},{"position":6,"title":"Đừng để nghi thức thay nội dung","text":"Giỏ trống và lễ vật không có thực gợi một thỏa thuận đủ hình thức mà thiếu đóng góp thật.","tip":"Kiểm cam kết có việc làm, nguồn lực và trách nhiệm tương ứng."}],"55":[{"position":1,"title":"Tìm người ngang sức phối hợp","text":"Gặp người cùng tầm gợi sự hợp tác có thể tạo sức sáng rõ khi hai bên bổ sung nhau.","tip":"Thống nhất vai trò và cách quyết định để năng lực không thành tranh nhau."},{"position":2,"title":"Làm rõ điều che ánh sáng","text":"Giữa trưa mà thấy sao gợi thông tin bị che; vội tiến dễ gặp nghi ngờ.","tip":"Đưa dữ kiện có thể kiểm và kiên nhẫn giải thích điều chưa rõ."},{"position":3,"title":"Chấp nhận giới hạn khi tầm nhìn bị che","text":"Ánh sáng khuất và gãy tay phải gợi khả năng thực thi đang bị hạn chế, không dự báo tổn thương thân thể.","tip":"Giảm phạm vi việc và tìm nguồn thông tin hoặc hỗ trợ bổ sung."},{"position":4,"title":"Tìm người đồng hành giữa thiếu sáng","text":"Bóng che dày mà gặp người ngang hàng gợi cùng kiểm sự việc có thể mở góc nhìn.","tip":"Nhờ một người độc lập rà giả định mình đang dùng."},{"position":5,"title":"Đón điều sáng rõ tới","text":"Cái đẹp có nội dung đến gợi cơ hội được ghi nhận khi phẩm chất và kết quả có thể thấy.","tip":"Chia sẻ thông tin hữu ích và ghi nhận người đã cùng góp sức."},{"position":6,"title":"Đừng tự khép trong sự đủ đầy","text":"Nhà lớn mà vắng người gợi sự cô lập khi chỉ chăm vẻ ngoài và che kín kết nối.","tip":"Mở lại một cuộc trao đổi chân thành với người quanh mình."}],"56":[{"position":1,"title":"Đừng mắc vào vụn vặt khi ở nơi lạ","text":"Người đi xa quá nhỏ nhen gợi va chạm dễ phát sinh vì không hiểu nếp chung hoặc chỉ giữ phần mình.","tip":"Hỏi quy tắc địa phương và chọn điều đáng quan tâm thật sự."},{"position":2,"title":"Giữ chỗ nghỉ và người đáng tin","text":"Có nơi tạm trú, nguồn lực và người giúp gợi ba điểm tựa cần thiết cho giai đoạn di chuyển.","tip":"Kiểm chỗ ở, vật thiết yếu và cách liên lạc với người hỗ trợ."},{"position":3,"title":"Bảo vệ quan hệ ở nơi tạm","text":"Chỗ trú cháy và mất người giúp gợi cái giá của cách sống làm hỏng nền an ổn tạm thời.","tip":"Tôn trọng người hỗ trợ và chuẩn bị phương án thay thế cho điều thiết yếu."},{"position":4,"title":"Có vật dụng chưa chắc đã yên lòng","text":"Tạm ở, có công cụ mà lòng chưa vui gợi sự đủ điều kiện vật chất vẫn còn thiếu cảm giác thuộc về.","tip":"Nhận rõ nhu cầu kết nối và giữ kỳ vọng phù hợp giai đoạn tạm thời."},{"position":5,"title":"Chấp nhận chi phí nhỏ để làm việc đúng","text":"Bắn chim mất một tên rồi được ghi nhận gợi giá trị có thể đòi hỏi một phần công sức hoặc hao hụt.","tip":"Cân chi phí trong giới hạn và làm tốt việc mình đảm nhận."},{"position":6,"title":"Đừng vui quá mà quên chỗ trú","text":"Tổ cháy, trước cười sau khóc gợi sự chủ quan với nền bảo vệ khi đang ở môi trường lạ.","tip":"Kiểm lại nguồn lực, người liên hệ và điều kiện an toàn của mình."}],"57":[{"position":1,"title":"Giữ quyết tâm giữa tiến lui","text":"Lưỡng lự tiến rồi lùi gợi cần sự rõ ràng, có kỷ luật để sức mềm không thành thiếu hướng.","tip":"Chốt một bước thử và thời điểm đánh giá thay vì thay ý liên tục."},{"position":2,"title":"Tìm hiểu sâu nhưng tránh tự hạ mình","text":"Ở dưới giường, nhiều người làm lễ gợi việc tìm điều ẩn cần thành tâm và nhiều cách kiểm.","tip":"Tìm nguyên nhân thực tế và hỏi đúng người, không giao hết quyền quyết định."},{"position":3,"title":"Đừng nhún nhường thành lặp lời","text":"Thuận nhiều lần gợi cách đồng ý rồi lại đổi có thể làm suy giảm tin cậy.","tip":"Nói rõ điều mình thực sự đồng ý và điều cần thương lượng."},{"position":4,"title":"Tiếp cận khéo có thể tạo kết quả","text":"Săn được nhiều loại gợi thành quả từ việc đã điều chỉnh cách tiếp cận phù hợp.","tip":"Ghi lại cách làm có ích và chia sẻ với người phối hợp."},{"position":5,"title":"Chuẩn bị trước, rà lại sau khi đổi","text":"Ba ngày trước sau mốc canh gợi thay đổi cần cả chuẩn bị lẫn theo dõi, không phải lịch bắt buộc cho mọi việc.","tip":"Đặt bước kiểm trước khi triển khai và một lần đánh giá sau đó."},{"position":6,"title":"Đừng nhún đến mất công cụ tự chủ","text":"Ở dưới giường và mất của, rìu gợi thích nghi quá mức có thể làm cạn khả năng tự quyết.","tip":"Giữ ranh giới cùng nguồn lực tối thiểu để tự chọn hướng đi."}],"58":[{"position":1,"title":"Niềm vui từ sự hòa nhã","text":"Sự vui hòa gợi kết nối nhẹ nhàng không cần mưu cầu hơn thua.","tip":"Tạo một cuộc trao đổi dễ chịu và tôn trọng nhịp của nhau."},{"position":2,"title":"Vui trên nền tin cậy","text":"Niềm vui có lòng thành gợi sự nhẹ nhõm bền hơn khi lời và cách làm khớp nhau.","tip":"Nói điều chân thực và giữ một lời hứa nhỏ."},{"position":3,"title":"Đừng chạy theo điều chỉ làm vui tai","text":"Niềm vui từ bên ngoài kéo tới gợi nguy cơ tìm sự tán thưởng thay cho nhu cầu thật.","tip":"Kiểm điều đang chiều ý mình có thực sự hữu ích hay không."},{"position":4,"title":"Cân nhắc trước khi hòa theo","text":"Bàn về niềm vui mà chưa yên gợi cần phân biệt điều nuôi dưỡng với điều đang làm khó mình.","tip":"Chọn kết nối giúp mình giữ nguyên tắc và giảm thói quen gây hao."},{"position":5,"title":"Đặt lòng tin đúng chỗ","text":"Tin vào điều đang bóc mòn gợi một mối gắn bó dễ làm suy nền nếu chỉ vì lời dễ nghe.","tip":"Quan sát hành vi và kiểm lại mức tin đã trao."},{"position":6,"title":"Nhận ra điều đang dẫn dắt cảm xúc","text":"Bị kéo vào niềm vui gợi sức hút có thể làm mình quên quyền lựa chọn.","tip":"Dừng một nhịp và hỏi mình có thật sự muốn tiếp tục hay không."}],"59":[{"position":1,"title":"Nhận trợ lực để thoát phân tán","text":"Ngựa khỏe dùng cứu gợi sự trợ giúp kịp lúc khi tình thế mới bắt đầu rời rạc. Biết tìm người có năng lực có thể giúp tránh để việc khó lớn thêm.","tip":"Nói rõ điều đang vướng và nhờ người phù hợp hỗ trợ từ sớm."},{"position":2,"title":"Chạy về một điểm tựa vững","text":"Tìm tới chiếc kỷ gợi trở về nơi có thể nương khi cảm thấy phân tán.","tip":"Giữ một nếp sinh hoạt hoặc kết nối giúp mình đứng vững."},{"position":3,"title":"Buông phần tự chấp để mở lối","text":"Làm tan sự vướng ở bản thân gợi bớt cái tôi có thể giải phóng cách hợp tác.","tip":"Chia sẻ điều mình đang cố bảo vệ và xem nó còn cần thiết không."},{"position":4,"title":"Vượt nhóm nhỏ để có mục tiêu chung","text":"Làm tan bè nhóm rồi thành gò gợi tái tổ chức các kết nối hẹp thành nền rộng hơn.","tip":"Tìm một mục tiêu có ích cho nhiều phía và phân trách nhiệm minh bạch."},{"position":5,"title":"Thông báo rõ trong lúc đổi lớn","text":"Mệnh lệnh lan như mồ hôi gợi thông tin cần tới người liên quan khi nguồn lực được phân lại.","tip":"Nói rõ điều thay đổi, lý do và nơi người dùng có thể hỏi."},{"position":6,"title":"Rời xa điều gây tổn hại","text":"Làm tan điều liên quan máu và đi xa gợi ưu tiên thoát khỏi nguồn đe dọa, không đoán sự cố sẽ đến.","tip":"Tìm khoảng cách an toàn và người hỗ trợ đáng tin khi cần."}],"60":[{"position":1,"title":"Biết lúc nên ở lại","text":"Không ra khỏi sân nhỏ gợi việc dừng đúng lúc khi điều kiện hành động chưa đủ rõ.","tip":"Hoàn tất phần chuẩn bị trước khi đưa kế hoạch ra ngoài."},{"position":2,"title":"Đừng biến giới hạn thành tự nhốt","text":"Không ra khỏi cổng lúc cần đi gợi sự giữ mình đã quá mức và làm lỡ việc.","tip":"Kiểm nỗi lo rồi chọn một bước tiếp xúc vừa sức."},{"position":3,"title":"Nhận ra cái giá của thiếu tiết chế","text":"Không biết giới hạn rồi than thở gợi cơ hội sửa nhịp sau một lần quá đà.","tip":"Xác định điều đã vượt sức và đặt giới hạn có thể duy trì."},{"position":4,"title":"Đặt giới hạn để thấy an ổn","text":"Sự tiết chế dễ chịu gợi một nếp sống phù hợp thay vì phải ép mình chịu mãi.","tip":"Chọn mức chi tiêu, làm việc hoặc giao tiếp vừa với điều kiện thật."},{"position":5,"title":"Giữ kỷ luật mà vẫn có niềm vui","text":"Tiết chế ngọt gợi sự tự chủ trở nên hữu ích khi người thực hiện hiểu và đồng thuận.","tip":"Làm rõ lợi ích của quy tắc và chừa khoảng linh hoạt hợp lý."},{"position":6,"title":"Nới sự khắc nghiệt đang gây khổ","text":"Giới hạn đắng gợi kỷ luật cực đoan có thể cần sửa, dù nhận ra giới hạn vẫn có ích.","tip":"Thay một tiêu chuẩn quá sức bằng nhịp có thể giữ lâu dài."}],"61":[{"position":1,"title":"An tâm nhờ chuẩn bị rõ","text":"Có sự liệu trước rồi mới yên gợi lòng tin không nên bị kéo đi bởi nhiều ý định phụ.","tip":"Làm rõ mục tiêu chính và các điều kiện mình cần xác nhận."},{"position":2,"title":"Sự chân thành có tiếng đáp","text":"Hạc kêu trong bóng, con hòa theo và cùng chia chén gợi kết nối không cần phô trương.","tip":"Chia sẻ điều có giá trị với người muốn cùng vun đắp."},{"position":3,"title":"Giữ nhịp khi cảm xúc đổi thất thường","text":"Gặp đối tác rồi lúc trống lúc thôi, lúc khóc lúc hát gợi phụ thuộc quá nhiều vào phản ứng người khác.","tip":"Nhận rõ nhu cầu của mình trước khi yêu cầu người kia làm mình yên."},{"position":4,"title":"Giữ hướng khi gần đầy","text":"Trăng gần tròn và cặp ngựa tách gợi việc giữ sự ngay thẳng khi một liên kết riêng kéo mình lệch trách nhiệm chung. Có thể điều chỉnh mức gắn bó và ưu tiên mà vẫn tôn trọng người liên quan.","tip":"Rà một cam kết đang xung đột với việc chung; trao đổi ranh giới trước khi thay đổi cách phối hợp."},{"position":5,"title":"Niềm tin nối người bằng việc làm","text":"Sợi ràng buộc bằng thành tín gợi ảnh hưởng của cam kết nhất quán trong quan hệ.","tip":"Giữ một thỏa thuận có thể kiểm và mời phản hồi thẳng thắn."},{"position":6,"title":"Đừng để tiếng vang vượt thực chất","text":"Tiếng chim vươn lên trời gợi lời tuyên bố lớn nhưng nền thực hiện có thể không theo kịp.","tip":"Đưa minh chứng trước lời hứa và hạ mức công bố khi chưa đủ nền."}],"62":[{"position":1,"title":"Đừng bay vượt sức khi việc cần nhỏ","text":"Chim bay gắn điều bất lợi gợi việc nhỏ chưa thuận cho một bước vươn quá cao.","tip":"Chọn mục tiêu gần và vừa khả năng kiểm soát."},{"position":2,"title":"Đến đúng người và đúng vai","text":"Đi qua bậc trước, gặp người phù hợp gợi hành động có chừng mực với vị trí và hoàn cảnh.","tip":"Hỏi đúng người phụ trách và tránh tự nhận phần quyền chưa có."},{"position":3,"title":"Tăng phòng bị ở chỗ dễ bỏ sót","text":"Không thêm phòng ngừa gợi rủi ro khi xem nhẹ những dấu hiệu sát mình.","tip":"Rà một điểm yếu nhỏ và bổ sung biện pháp bảo vệ tương xứng."},{"position":4,"title":"Điều chỉnh thay vì giữ cứng mãi","text":"Gặp đúng mức mà chưa nên tiến xa gợi sự phù hợp cần theo tình huống, không thành một khuôn bất biến.","tip":"Kiểm lại điều kiện trước mỗi bước và chừa quyền đổi cách làm."},{"position":5,"title":"Tìm điều trong tầm tay khi chưa có mưa","text":"Mây dày chưa mưa, tìm vật trong hang gợi tiềm năng chưa thành kết quả rộng nhưng việc gần còn làm được.","tip":"Làm một việc nhỏ có dữ kiện rõ thay vì chờ điều lớn."},{"position":6,"title":"Tránh vượt quá điểm có thể gặp","text":"Chim bay quá xa gợi sự lỡ nhịp vì đi vượt mức cần thiết.","tip":"Đặt điểm dừng và quay lại mục tiêu thực trước khi mở thêm việc."}],"63":[{"position":1,"title":"Chậm lại khi vừa qua được","text":"Kéo bánh xe, ướt đuôi gợi một sự kiềm đà giúp tránh sơ suất lúc chuyển tiếp.","tip":"Kiểm bước cuối và không tăng tốc chỉ vì đã gần xong."},{"position":2,"title":"Đừng đuổi theo phần nhỏ bị mất","text":"Mất màn che rồi còn lấy lại gợi có điều tạm thiếu chưa đáng làm mình bỏ toàn bộ nhịp chính.","tip":"Giữ việc thiết yếu và kiểm cách phục hồi theo thứ tự."},{"position":3,"title":"Dự liệu công sức cho việc khó kéo dài","text":"Chiến dịch ba năm gợi mục tiêu lớn cần nguồn lực, năng lực và sự bền, không phải mốc thời gian dự báo.","tip":"Ước lượng chi phí dài hạn và chọn người có năng lực phù hợp."},{"position":4,"title":"Giữ sẵn phương án vá chỗ rò","text":"Áo rách và vật để vá gợi sự phòng ngừa sau khi công việc tưởng đã ổn.","tip":"Kiểm một điểm dễ hỏng và chuẩn bị cách sửa trước."},{"position":5,"title":"Thành ý hơn quy mô lễ vật","text":"Lễ lớn không bằng lễ nhỏ đúng lòng gợi chất lượng cam kết quan trọng hơn mức phô trương.","tip":"Dùng nguồn lực cho điều thực có ích thay vì tạo vẻ đầy đủ."},{"position":6,"title":"Đừng để thành công làm mất cảnh giác","text":"Ướt đầu gợi tiến quá mức an toàn sau khi đã qua được một chặng.","tip":"Dừng ở điểm đủ và rà điều kiện trước khi nhận thêm rủi ro."}],"64":[{"position":1,"title":"Đừng vội ở lúc chưa qua được","text":"Ướt đuôi gợi khởi sự khi điều kiện còn thiếu có thể gây vướng ngay đầu.","tip":"Làm rõ điều chưa chuẩn bị xong trước khi bắt tay."},{"position":2,"title":"Giữ bánh xe trong tầm điều khiển","text":"Kéo bánh xe gợi tự chế để không bị đà việc cuốn vào bước chưa sẵn sàng.","tip":"Giảm tốc và kiểm khả năng điều chỉnh trước khi tiến."},{"position":3,"title":"Phân biệt lao tới với vượt qua có chuẩn bị","text":"Chưa xong mà cứ tiến có khó, trong khi qua sông vẫn là việc cần làm khi đủ điều kiện.","tip":"Tìm phương tiện và sự phối hợp trước khi chọn bước chuyển lớn."},{"position":4,"title":"Kiên trì với nhiệm vụ có nền","text":"Chiến dịch dài rồi được thưởng gợi thành quả gắn năng lực theo đuổi đến cùng, không hứa mốc ba năm cho người dùng.","tip":"Đặt từng mốc đánh giá và giữ nguồn lực cho chặng dài."},{"position":5,"title":"Giữ sự sáng và thành thực lúc gần xong","text":"Ánh sáng của người quân tử cùng lòng tin gợi tiến triển được nâng bằng cách làm minh bạch.","tip":"Công bố điều đã đạt và điều còn thiếu một cách trung thực."},{"position":6,"title":"Vui mà đừng mất chừng mực","text":"Có lòng tin lúc uống nhưng ướt đầu gợi thoải mái sau nỗ lực vẫn cần giới hạn để khỏi làm hỏng việc.","tip":"Giữ sự tỉnh táo, kiểm bước cuối trước khi tuyên bố hoàn thành."}]};
